* {
  box-sizing: border-box;
  scrollbar-color: var(--scrollbar-thumb-hidden) transparent;
  scrollbar-width: thin;
}

.page-home-button {
  display: inline-flex;
  height: 32px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--page-home-button-border);
  border-radius: 9px;
  background: var(--page-home-button-bg);
  padding: 0 11px;
  color: var(--page-home-button-text);
  box-shadow: var(--page-home-button-shadow);
  cursor: pointer;
  font-family: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 650;
  line-height: 1;
  transition: border-color 0.15s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.page-home-button svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.page-home-button:hover:not(:disabled) {
  background: var(--page-home-button-bg-hover);
}

.page-home-button:active:not(:disabled) {
  background: var(--page-home-button-bg-active);
  transform: translateY(1px);
}

.page-home-button:focus-visible {
  outline: 0;
  box-shadow: var(--page-home-button-shadow), 0 0 0 3px var(--page-home-button-focus);
}

.page-home-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  box-shadow: none;
}

.page-home-nav-row {
  display: flex;
  height: 48px;
  flex: 0 0 auto;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
}

/* Haolo Chrome integration center: light and dark states ship together. */
.plugin-chrome-manage {
  min-width: 54px;
  height: 30px;
  border: 1px solid var(--border-control);
  border-radius: 9px;
  background: var(--surface-field);
  color: var(--text-primary);
  font-size: calc(12px + var(--app-font-size-offset));
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.plugin-chrome-manage:hover { background: var(--surface-interactive-hover); border-color: var(--brand-blue); }
.plugin-chrome-manage:active { transform: translateY(1px); }
.plugin-chrome-manage:focus-visible { outline: 3px solid color-mix(in srgb, var(--brand-blue) 34%, transparent); outline-offset: 2px; }
.plugin-chrome-manage:disabled { cursor: not-allowed; opacity: 0.46; transform: none; }

.chrome-integration-backdrop { z-index: 1280; background: rgba(3, 7, 18, 0.48); backdrop-filter: blur(5px); }
.chrome-integration-dialog {
  position: fixed;
  z-index: 1281;
  inset: 50% auto auto 50%;
  transform: translate(-50%, -50%);
  width: min(920px, calc(100vw - 48px));
  max-height: min(860px, calc(100vh - 48px));
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 22px;
  background: var(--surface-primary);
  color: var(--text-primary);
  box-shadow: 0 28px 90px rgba(15, 23, 42, 0.28);
}

.chrome-integration-header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 20px 22px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(135deg, color-mix(in srgb, var(--brand-blue) 8%, var(--surface-primary)), var(--surface-primary) 58%);
}

.chrome-integration-mark {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 15px;
  background: linear-gradient(145deg, #4f7cff, #8257ed);
  color: #fff;
  font-size: calc(18px + var(--app-font-size-offset));
  font-weight: 800;
  box-shadow: 0 10px 24px rgba(79, 124, 255, 0.26);
}

.chrome-integration-eyebrow, .chrome-section-kicker { color: var(--brand-blue); font-size: calc(10px + var(--app-font-size-offset)); font-weight: 780; letter-spacing: 0.1em; }
.chrome-integration-header h2 { margin: 3px 0 0; font-size: calc(21px + var(--app-font-size-offset)); line-height: 1.25; }
.chrome-integration-header p { margin: 4px 0 0; color: var(--text-subtle); font-size: calc(12px + var(--app-font-size-offset)); }
.chrome-integration-close {
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--text-secondary);
  font-size: calc(24px + var(--app-font-size-offset));
  line-height: 1;
  cursor: pointer;
}
.chrome-integration-close:hover:not(:disabled) { border-color: var(--line); background: var(--surface-hover); color: var(--text-primary); }
.chrome-integration-close:active:not(:disabled) { background: var(--surface-active-translucent); }
.chrome-integration-close:focus-visible { outline: 3px solid color-mix(in srgb, var(--brand-blue) 34%, transparent); outline-offset: 2px; }
.chrome-integration-close:disabled { cursor: not-allowed; opacity: 0.38; }

.chrome-integration-body { display: grid; gap: 16px; max-height: calc(min(860px, 100vh - 48px) - 88px); padding: 18px 22px 22px; overflow: auto; background: var(--surface-subtle); }
.chrome-integration-loading { display: flex; align-items: center; justify-content: center; gap: 10px; min-height: 120px; color: var(--text-subtle); font-size: calc(13px + var(--app-font-size-offset)); }
.chrome-health-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.chrome-health-item { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; min-height: 104px; padding: 13px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-primary); }
.chrome-health-dot { width: 9px; height: 9px; margin-top: 5px; border-radius: 99px; background: var(--contact-status-standby); box-shadow: 0 0 0 4px color-mix(in srgb, var(--contact-status-standby) 13%, transparent); }
.chrome-health-item[data-tone="ready"] .chrome-health-dot { background: var(--green); box-shadow: 0 0 0 4px color-mix(in srgb, var(--green) 13%, transparent); }
.chrome-health-item[data-tone="danger"] .chrome-health-dot { background: var(--danger); box-shadow: 0 0 0 4px color-mix(in srgb, var(--danger) 13%, transparent); }
.chrome-health-item div { min-width: 0; display: grid; align-content: start; gap: 3px; }
.chrome-health-item small { color: var(--text-subtle); font-size: calc(10px + var(--app-font-size-offset)); }
.chrome-health-item strong { font-size: calc(14px + var(--app-font-size-offset)); }
.chrome-health-item p { margin: 2px 0 0; color: var(--text-subtle); font-size: calc(10px + var(--app-font-size-offset)); line-height: 1.45; }

.chrome-setup-card, .chrome-approval-section, .chrome-audit-section { padding: 16px; border: 1px solid var(--line); border-radius: 16px; background: var(--surface-primary); }
.chrome-setup-card { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 18px; }
.chrome-setup-card h3, .chrome-section-heading h3 { margin: 4px 0 0; font-size: calc(15px + var(--app-font-size-offset)); }
.chrome-setup-card p { max-width: 540px; margin: 6px 0 0; color: var(--text-subtle); font-size: calc(11px + var(--app-font-size-offset)); line-height: 1.55; }
.chrome-setup-actions { display: flex; max-width: 330px; flex-wrap: wrap; justify-content: flex-end; gap: 7px; }
.chrome-setup-actions button, .chrome-approval-actions button {
  min-height: 32px;
  padding: 7px 11px;
  border: 1px solid var(--control-primary);
  border-radius: 9px;
  background: var(--control-primary);
  color: var(--surface-primary);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 650;
  cursor: pointer;
  transition: background 0.14s ease, border-color 0.14s ease, transform 0.1s ease, opacity 0.14s ease;
}
.chrome-setup-actions button.secondary, .chrome-approval-actions button.secondary { border-color: var(--border-control); background: var(--surface-field); color: var(--text-primary); }
.chrome-setup-actions button.ghost, .chrome-approval-actions button.ghost { border-color: transparent; background: transparent; color: var(--text-secondary); }
.chrome-approval-actions button.danger { color: var(--danger); }
.chrome-setup-actions button:hover:not(:disabled), .chrome-approval-actions button:hover:not(:disabled) { transform: translateY(-1px); background: var(--control-primary-hover); }
.chrome-setup-actions button.secondary:hover:not(:disabled), .chrome-approval-actions button.secondary:hover:not(:disabled), .chrome-setup-actions button.ghost:hover:not(:disabled), .chrome-approval-actions button.ghost:hover:not(:disabled) { background: var(--surface-interactive-hover); border-color: var(--line-strong); }
.chrome-setup-actions button:active:not(:disabled), .chrome-approval-actions button:active:not(:disabled) { transform: translateY(0); }
.chrome-setup-actions button:focus-visible, .chrome-approval-actions button:focus-visible { outline: 3px solid color-mix(in srgb, var(--brand-blue) 34%, transparent); outline-offset: 2px; }
.chrome-setup-actions button:disabled, .chrome-approval-actions button:disabled { cursor: not-allowed; opacity: 0.42; transform: none; }

.chrome-section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
.chrome-count-badge { min-width: 25px; padding: 4px 8px; border-radius: 99px; background: color-mix(in srgb, var(--brand-blue) 12%, var(--surface-primary)); color: var(--brand-blue); text-align: center; font-size: calc(11px + var(--app-font-size-offset)); font-weight: 750; }
.chrome-approval-list { display: grid; gap: 9px; }
.chrome-approval-card { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 12px; border: 1px solid var(--line); border-radius: 13px; background: var(--surface-subtle); }
.chrome-approval-card[data-effect="high_impact"] { border-color: color-mix(in srgb, var(--danger) 38%, var(--line)); }
.chrome-approval-copy { min-width: 0; display: grid; gap: 4px; }
.chrome-approval-copy strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: calc(12px + var(--app-font-size-offset)); }
.chrome-approval-copy span { color: var(--text-subtle); font-size: calc(10px + var(--app-font-size-offset)); }
.chrome-approval-copy em { color: var(--contact-status-standby); font-size: calc(10px + var(--app-font-size-offset)); font-style: normal; }
.chrome-approval-actions { flex: 0 0 auto; display: flex; gap: 7px; }
.chrome-empty-state { display: grid; place-items: center; min-height: 84px; gap: 5px; padding: 14px; border: 1px dashed var(--line-strong); border-radius: 12px; color: var(--text-subtle); text-align: center; }
.chrome-empty-state strong { color: var(--text-secondary); font-size: calc(12px + var(--app-font-size-offset)); }
.chrome-empty-state span { font-size: calc(10px + var(--app-font-size-offset)); }
.chrome-empty-state.compact { min-height: 54px; }
.chrome-audit-list { display: grid; gap: 0; margin: 0; padding: 0; list-style: none; }
.chrome-audit-list li { display: grid; grid-template-columns: 66px minmax(0, 1fr); gap: 10px; padding: 8px 2px; border-bottom: 1px solid var(--line); }
.chrome-audit-list li:last-child { border-bottom: 0; }
.chrome-audit-list time { color: var(--text-muted); font-size: calc(10px + var(--app-font-size-offset)); font-variant-numeric: tabular-nums; }
.chrome-audit-list div { min-width: 0; display: grid; gap: 2px; }
.chrome-audit-list strong { font-size: calc(11px + var(--app-font-size-offset)); }
.chrome-audit-list span { overflow: hidden; color: var(--text-subtle); font-size: calc(10px + var(--app-font-size-offset)); text-overflow: ellipsis; white-space: nowrap; }
.chrome-artifact-feedback, .chrome-integration-warning, .chrome-integration-error { margin: 0; padding: 10px 12px; border-radius: 10px; font-size: calc(11px + var(--app-font-size-offset)); }
.chrome-artifact-feedback { background: color-mix(in srgb, var(--green) 11%, var(--surface-primary)); color: var(--green); }
.chrome-integration-warning { background: color-mix(in srgb, var(--contact-status-standby) 13%, var(--surface-primary)); color: var(--contact-status-standby); }
.chrome-integration-error { background: color-mix(in srgb, var(--danger) 11%, var(--surface-primary)); color: var(--danger); }

html[data-theme="dark"] .chrome-integration-backdrop { background: rgba(0, 0, 0, 0.68); }
html[data-theme="dark"] .chrome-integration-dialog { border-color: #383e48; box-shadow: 0 34px 100px rgba(0, 0, 0, 0.62); }
html[data-theme="dark"] .chrome-integration-header { background: linear-gradient(135deg, rgba(91, 157, 255, 0.13), var(--surface-primary) 60%); }
html[data-theme="dark"] .chrome-health-item, html[data-theme="dark"] .chrome-setup-card, html[data-theme="dark"] .chrome-approval-section, html[data-theme="dark"] .chrome-audit-section { border-color: #303640; }
html[data-theme="dark"] .chrome-approval-card { background: #181b20; border-color: #303640; }
html[data-theme="dark"] .chrome-setup-actions button:not(.secondary):not(.ghost), html[data-theme="dark"] .chrome-approval-actions button:not(.secondary):not(.ghost) { border-color: #eef1f6; background: #eef1f6; color: #111318; }
html[data-theme="dark"] .chrome-setup-actions button:not(.secondary):not(.ghost):hover:not(:disabled), html[data-theme="dark"] .chrome-approval-actions button:not(.secondary):not(.ghost):hover:not(:disabled) { border-color: #fff; background: #fff; }

@media (max-width: 1350px) {
  .recharge-payment-methods {
    height: auto;
    align-items: start;
