#windowResizeRoot.right-scrollbar-interaction .window-resize-handle.e,
#windowResizeRoot.right-scrollbar-interaction .window-resize-handle.ne,
#windowResizeRoot.right-scrollbar-interaction .window-resize-handle.se {
  pointer-events: none;
}

#windowResizeRoot.bottom-scrollbar-interaction .window-resize-handle.s,
#windowResizeRoot.bottom-scrollbar-interaction .window-resize-handle.se,
#windowResizeRoot.bottom-scrollbar-interaction .window-resize-handle.sw {
  pointer-events: none;
}

.window-resize-handle.ne,
.window-resize-handle.nw,
.window-resize-handle.se,
.window-resize-handle.sw {
  width: var(--window-resize-corner);
  height: var(--window-resize-corner);
}

.window-resize-handle.ne {
  top: 0;
  right: 0;
  height: var(--window-top-resize-gutter);
  cursor: nesw-resize !important;
}

.window-resize-handle.nw {
  top: 0;
  left: 0;
  height: var(--window-top-resize-gutter);
  cursor: nwse-resize !important;
}

.window-resize-handle.se {
  right: 0;
  bottom: 0;
  cursor: nwse-resize !important;
}

.window-resize-handle.sw {
  bottom: 0;
  left: 0;
  cursor: nesw-resize !important;
}

html.window-maximized .window-resize-handle {
  display: none;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes thinking-dot {
  0%,
  80%,
  100% {
    opacity: 0.35;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

@keyframes media-generation-dot {
  0%,
  100% {
    opacity: calc(var(--dot-opacity) * 0.36);
    transform: translate3d(var(--dot-x1), var(--dot-y1), 0) scale(calc(var(--dot-scale) * 0.58));
  }
  18% {
    opacity: calc(var(--dot-peak) * 0.72);
    transform: translate3d(var(--dot-x2), var(--dot-y2), 0) scale(calc(var(--dot-scale) * 0.82));
  }
  39% {
    opacity: var(--dot-peak);
    transform: translate3d(var(--dot-x3), var(--dot-y3), 0) scale(var(--dot-scale));
  }
  61% {
    opacity: calc(var(--dot-peak) * 0.58);
    transform: translate3d(var(--dot-x4), var(--dot-y4), 0) scale(calc(var(--dot-scale) * 0.72));
  }
  82% {
    opacity: calc(var(--dot-opacity) * 0.92);
    transform: translate3d(calc(var(--dot-x2) * -0.45), calc(var(--dot-y3) * -0.45), 0) scale(calc(var(--dot-scale) * 0.66));
  }
}

@keyframes media-generation-sheen {
  0%,
  100% {
    background-position: 10% 22%, 82% 72%, 0% 40%;
  }
  33% {
    background-position: 64% 28%, 34% 86%, 52% 54%;
  }
  67% {
    background-position: 34% 78%, 76% 36%, 100% 60%;
  }
}

@keyframes login-caret-blink {
  0%,
  50% {
    opacity: 1;
  }
  51%,
  100% {
    opacity: 0;
  }
}

button,
input,
textarea,
select {
  font: inherit;
  -webkit-app-region: no-drag;
}

dialog textarea {
  resize: none;
}

button {
  border: 0;
  background: transparent;
  cursor: pointer;
  -webkit-app-region: no-drag;
  -webkit-user-drag: none;
}

button * {
  -webkit-user-drag: none;
}

/* English action labels stay horizontal and can grow past legacy CJK widths. */
html[data-language="en"] button[data-i18n-single-line] {
  box-sizing: border-box;
  min-inline-size: max-content;
  overflow-wrap: normal;
  word-break: normal;
  white-space: nowrap;
  hyphens: none;
}

.button-close-icon {
  display: block;
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  object-fit: contain;
  pointer-events: none;
}

[data-file-drag] {
  cursor: grab;
  -webkit-user-drag: element;
}

[data-file-drag]:active {
  cursor: grabbing;
}

button:disabled,
input:disabled,
textarea:disabled,
select:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.login-shell {
  position: fixed;
  inset: 0;
  z-index: 5;
  display: grid;
  width: 100%;
  height: 100%;
  flex: 1;
  min-height: 0;
  place-items: center;
  overflow: hidden;
  border: 0;
  border-radius: var(--window-radius);
  clip-path: inset(0 round var(--window-radius));
  background: transparent;
  padding: 0;
  box-shadow: none;
  -webkit-app-region: drag;
}

.login-card {
  position: relative;
  display: grid;
  width: 100%;
  height: 100%;
  align-content: start;
  border: 1px solid #d9d9d9;
  border-radius: var(--window-radius);
  clip-path: inset(0 round var(--window-radius));
  background: var(--surface-primary);
  padding: 18px 42px 24px;
  box-shadow: none;
  -webkit-app-region: drag;
}

.login-card-activate {
  padding-bottom: 34px;
  -webkit-app-region: drag;
}

.login-card input,
.login-card button,
.login-fields,
.login-footnote,
.login-footnote * {
  -webkit-app-region: no-drag;
}

.login-card button {
  border-radius: 999px;
}

.login-close-button {
  position: absolute;
  top: 16px;
  right: 16px;
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 999px;
  color: #a3a3a3;
  padding: 0;
  outline: 0;
}

.login-close-button:hover {
  background: var(--surface-hover);
  color: var(--text-primary-soft);
}

.login-close-button:focus,
.login-close-button:focus-visible {
  outline: 0;
  box-shadow: none;
}

