  font-weight: 700;
  line-height: 28px;
}

.login-restore-panel .login-submit {
  margin-top: 70px;
}

.login-restore-back {
  margin-top: 18px;
  border-radius: 999px;
  padding: 2px 12px;
  color: #8f8f8f;
  font-size: calc(16px + var(--app-font-size-offset));
  line-height: 24px;
}

.login-code-panel {
  padding-top: 100px;
}

.login-code-panel p,
.login-code-panel strong {
  margin: 0;
  font-size: calc(18px + var(--app-font-size-offset));
  line-height: 28px;
}

.login-code-panel p {
  color: #a6a6a6;
}

.login-code-panel strong {
  color: var(--text-near-black);
