}

.login-link-button {
  margin-top: 8px;
  border-radius: 999px;
  padding: 1px 8px;
  color: #8f8f8f;
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 22px;
}

.login-link-button:disabled {
  color: #8f8f8f;
  opacity: 0.45;
}

.login-secondary-restart {
  display: block;
  margin: 18px auto 0;
}

.login-code-panel > .login-link-button {
  margin-top: 16px;
}

.login-code-actions {
  display: grid;
  justify-items: center;
  margin-top: 12px;
  gap: 12px;
}

.login-otp-wrap + .login-code-actions {
