}

.login-code-actions .login-link-button {
  margin-top: 0;
}

.login-code-countdown {
  color: #8f8f8f;
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 22px;
}

.login-resend-button {
  color: #8f8f8f;
}

.login-activate-panel {
