}

.login-avatar-picker {
  display: grid;
  justify-items: center;
  margin-bottom: 34px;
  color: #b6b6b6;
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 22px;
}

.login-avatar-picker button {
  display: grid;
  width: 100px;
  height: 100px;
