  height: 18px;
  min-height: 18px;
  margin: 8px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.login-activate-help {
  margin: 22px 0 0;
  color: var(--text-near-black);
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 22px;
}

.login-activate-help button {
  border-radius: 999px;
  color: var(--brand-blue);
  font-size: inherit;
  font-weight: 400;
  line-height: inherit;
  padding: 0;
}

.login-activate-panel .login-submit {
  margin-top: 36px;
}

.login-card-activate .login-avatar-picker,
.login-card-activate .login-activate-fields,
.login-card-activate .login-activate-error {
  transform: translateY(-30px);
}

.login-card-activate .login-submit,
.login-card-activate .login-activate-help {
  transform: translateY(-55px);
}

.login-avatar-picker,
.login-avatar-picker *,
.login-activate-fields,
.login-activate-fields *,
.login-activate-help,
.login-activate-help * {
  -webkit-app-region: no-drag;
}

.login-success-panel {
  padding-top: 56px;
}

.login-success-badge {
  width: 94px;
  height: 94px;
}

.login-success-badge img {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 22px;
  object-fit: cover;
}

.login-success-panel h2 {
  margin: 20px 0 8px;
  color: var(--text-black);
  font-size: calc(22px + var(--app-font-size-offset));
  line-height: 30px;
}

.login-success-panel p {
  margin: 0;
  color: var(--text-black);
  font-size: calc(20px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 30px;
}

.login-citizen-row {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 56px 0 10px;
  transform: translateY(-10px);
}

.login-success-panel .login-citizen-label {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 0;
  margin: 0;
  color: #a1a1aa;
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 18px;
  text-align: left;
  white-space: nowrap;
}

.login-citizen-row strong {
  color: var(--text-black);
  font-size: calc(36px + var(--app-font-size-offset));
  line-height: 44px;
  transform: translateY(-4px);
}

.login-citizen-row button {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 999px;
  color: var(--text-muted);
}

.login-citizen-row svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.4;
}

.desktop-shell {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border-translucent);
  border-radius: var(--window-radius);
  clip-path: inset(0 round var(--window-radius));
  background: rgba(246, 248, 250, 0.82);
  backdrop-filter: blur(200px) saturate(0.72) brightness(1.12) contrast(0.08);
  -webkit-backdrop-filter: blur(200px) saturate(0.72) brightness(1.12) contrast(0.08);
  box-shadow:
    0 18px 42px rgba(15, 23, 42, 0.14),
    0 3px 10px rgba(15, 23, 42, 0.08);
}

.desktop-shell::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.38)),
    linear-gradient(90deg, rgba(255, 255, 255, 0.38), rgba(255, 255, 255, 0.18) 52%, rgba(255, 255, 255, 0.34)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.12) 0 1px, rgba(255, 255, 255, 0) 1px 4px);
  content: "";
  pointer-events: none;
}

.window-maximized .desktop-shell {
  border-radius: 0;
  clip-path: none;
}

.desktop-body {
  position: relative;
  z-index: 1;
  display: flex;
  width: 100%;
  min-height: 0;
  flex: 1;
  margin: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0 var(--window-content-radius) 0 0;
  clip-path: inset(0 round 0 var(--window-content-radius) 0 0);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.58) 0%, rgba(255, 255, 255, 0.5) 100%),
    linear-gradient(
      90deg,
      rgba(255, 244, 242, 0.66) 0%,
      rgba(247, 253, 244, 0.66) 36%,
      rgba(244, 250, 253, 0.64) 68%,
      rgba(249, 247, 255, 0.66) 100%
    );
}

.desktop-body::before,
.desktop-body::after {
  position: absolute;
  top: 0;
  z-index: 4;
  width: var(--window-content-radius);
  height: var(--window-content-radius);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.38)),
    linear-gradient(90deg, rgba(255, 255, 255, 0.38), rgba(255, 255, 255, 0.18) 52%, rgba(255, 255, 255, 0.34)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.12) 0 1px, rgba(255, 255, 255, 0) 1px 4px);
  content: "";
  pointer-events: none;
}

.desktop-body::before {
  display: none;
  left: 0;
  mask-image: radial-gradient(circle at bottom right, transparent calc(var(--window-content-radius) - 0.75px), #000 var(--window-content-radius));
  -webkit-mask-image: radial-gradient(circle at bottom right, transparent calc(var(--window-content-radius) - 0.75px), #000 var(--window-content-radius));
}

.desktop-body::after {
  right: 0;
  mask-image: radial-gradient(circle at bottom left, transparent calc(var(--window-content-radius) - 0.75px), #000 var(--window-content-radius));
  -webkit-mask-image: radial-gradient(circle at bottom left, transparent calc(var(--window-content-radius) - 0.75px), #000 var(--window-content-radius));
}

.app-titlebar {
  position: relative;
  z-index: 100;
  display: flex;
  height: 38px;
  flex-shrink: 0;
  align-items: center;
  gap: 10px;
  justify-content: flex-start;
  background: var(--app-chrome-background);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border-bottom: 0;
  border-radius: inherit;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
  overflow: visible;
  padding: 0 0 0 15px;
  cursor: move;
  -webkit-app-region: no-drag;
  user-select: none;
}

.app-titlebar.mac-titlebar {
  padding-left: 0;
}

.mac-traffic-light-spacer {
  width: var(--mac-traffic-light-width);
  height: 100%;
