}

.app-titlebar::before {
  display: none;
}

.window-maximized .app-titlebar {
  border-radius: 0;
}

.app-titlebar > * {
  position: relative;
  z-index: 1;
}

.left-panel-toggle {
  position: absolute;
  top: 6px;
  left: 0;
  z-index: 110;
  cursor: pointer;
  transition: color 0.18s ease, background-color 0.18s ease;
  -webkit-app-region: no-drag;
}

.left-panel-toggle:focus-visible {
  outline: 2px solid rgba(37, 99, 235, 0.28);
  outline-offset: 2px;
}

.desktop-shell.left-panel-collapsed .left-panel-toggle {
  top: 6px;
  left: 0;
}

/* Trading Expert keeps the left-panel control in the titlebar, immediately
   before the profile avatar. Other workspaces continue using the body anchor. */
.app-titlebar > .titlebar-left-panel-toggle {
  position: relative;
  top: auto;
  left: auto;
  width: 24px;
  height: 30px;
  flex: 0 0 24px;
  margin-left: -7px;
  margin-right: -1px;
  border-radius: 8px;
}

.app-titlebar > .titlebar-left-panel-toggle:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 2px var(--conversation-action-focus);
}

.desktop-shell.left-panel-collapsed .app-titlebar > .titlebar-left-panel-toggle {
  top: auto;
  left: auto;
}

