  position: relative;
  z-index: 2;
  background: var(--surface-glass);
  box-shadow: -1px 0 0 rgba(229, 231, 235, 0.5);
  overflow: hidden;
}

.desktop-body > aside.chat-list {
  z-index: 30;
  overflow: visible;
}

.desktop-body > .chat-list {
  transition:
    width 0.24s ease,
    max-width 0.24s ease,
    border-color 0.24s ease;
  will-change: width, max-width;
}

.desktop-body.left-panel-collapsed > .chat-list {
  width: 0;
  max-width: 0;
  min-width: 0;
  border-right-color: transparent;
  overflow: hidden;
  pointer-events: none;
}

.desktop-body.left-panel-collapsed > .chat-panel {
  border-top-left-radius: inherit;
  border-top-right-radius: inherit;
  box-shadow: none;
}

.desktop-shell:not(.left-panel-collapsed) .desktop-body > .chat-panel .chat-header {
  padding-left: 44px;
}

.desktop-body.left-panel-collapsed > .chat-panel .chat-header {
  padding-left: 48px;
}

.desktop-body.left-panel-collapsed > .chat-panel::after {
  display: none;
}

.desktop-body > .chat-panel {
  border-top-right-radius: inherit;
  border-bottom-right-radius: 0;
}

.desktop-body.right-panel-collapsed > .chat-panel {
  border-top-right-radius: inherit;
  box-shadow:
    -1px 0 0 rgba(229, 231, 235, 0.5),
    1px 0 0 rgba(229, 231, 235, 0.5);
}

.desktop-body.right-panel-collapsed > .chat-panel::after {
  position: absolute;
  top: 0;
  right: -1px;
  bottom: 0;
  width: 1px;
  background: var(--surface-glass);
  content: "";
  pointer-events: none;
}

.desktop-body.right-panel-collapsed > .agent-panel.collapsed {
  display: none;
}

.desktop-body > :first-child {
  border-top-left-radius: inherit;
}

.desktop-body > :last-child {
  border-top-right-radius: inherit;
  border-bottom-right-radius: 0;
  overflow: hidden;
}

.desktop-body > .contact-profile-page,
.desktop-body > .contact-requests-page,
.desktop-body > .contact-chat-page {
  border-top-right-radius: inherit;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
}

.desktop-body > .agent-panel {
