}

.turn-result-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  height: auto;
  margin: 0 0 8px;
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--text-tertiary);
  cursor: pointer;
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 16px;
  letter-spacing: 0;
}

.turn-result-toggle:hover,
.turn-result-toggle:focus-visible {
  color: var(--text-secondary);
}

.turn-result-toggle i {
  display: inline-flex;
  width: 10px;
  height: 16px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  transition: transform 0.12s ease;
}

.turn-result-toggle i::before {
  display: block;
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(-45deg);
