}

.turn-result-toggle.expanded i {
  transform: rotate(45deg);
}

.conversation-supplement-status-wrap {
  margin: 0 0 8px;
}

.conversation-supplement-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  height: auto;
  margin: 0 0 8px;
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--text-tertiary);
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 16px;
  letter-spacing: 0;
}

.conversation-supplement-status-wrap .conversation-supplement-status {
  margin-bottom: 4px;
}

.conversation-supplement-status-toggle {
  cursor: pointer;
}

.conversation-supplement-status-toggle:hover,
.conversation-supplement-status-toggle:focus-visible {
  color: var(--text-secondary);
}

.conversation-supplement-status-toggle i {
  display: inline-flex;
  width: 10px;
  height: 16px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  transition: transform 0.12s ease;
}

.conversation-supplement-status-toggle i::before {
  display: block;
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(-45deg);
