}

.conversation-supplement-status-toggle.expanded i {
  transform: rotate(45deg);
}

.conversation-supplement-reason {
  color: #7b818b;
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 16px;
