}

.thinking-row .message-meta {
  display: none;
}

.local-group-thinking-row .message-meta {
  display: block;
}

.local-group-thinking-row .thinking-text {
  background: var(--bubble-agent);
}

.context-compaction-row .message-meta {
  display: none;
}

.subagent-status-row .message-meta {
  display: none;
}

.media-generation-row .message-meta {
  display: none;
}

.media-generation-row .message-stack {
  width: min(340px, calc(100% - 44px));
  max-width: calc(100% - 44px);
}

.subagent-status-row .message-stack {
  width: min(620px, calc(100% - 44px));
  max-width: calc(100% - 44px);
}

.subagent-status-row > .message-avatar {
  margin-top: 5px;
}

.subagent-cluster {
  position: relative;
  width: 100%;
  margin-top: 3px;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  padding: 0;
}

.subagent-cluster-header {
  display: grid;
  min-height: 38px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 2px 4px 10px;
}

.subagent-cluster-mark {
  position: relative;
  width: 24px;
  height: 24px;
  flex: 0 0 auto;
  border: 1px solid rgba(22, 119, 255, 0.18);
  border-radius: 8px;
  background: linear-gradient(145deg, #f3f8ff, #eaf3ff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.subagent-cluster-mark::before,
.subagent-cluster-mark::after {
  position: absolute;
  content: "";
}

.subagent-cluster-mark::before {
  top: 7px;
  left: 7px;
  width: 9px;
  height: 8px;
  border-bottom: 1.5px solid #5b8fdc;
  border-left: 1.5px solid #5b8fdc;
  border-radius: 0 0 0 4px;
}

.subagent-cluster-mark::after {
  top: 5px;
  left: 11px;
  width: 1.5px;
  height: 11px;
  border-radius: 999px;
  background: #5b8fdc;
}

.subagent-cluster-mark i {
  position: absolute;
  z-index: 1;
  width: 4px;
  height: 4px;
  border: 1px solid #5b8fdc;
  border-radius: 50%;
  background: #f6faff;
}

.subagent-cluster-mark i:nth-child(1) {
  top: 3px;
  left: 9.5px;
}

.subagent-cluster-mark i:nth-child(2) {
  bottom: 3px;
  left: 5px;
}

.subagent-cluster-mark i:nth-child(3) {
  right: 5px;
  bottom: 3px;
}

.subagent-cluster-summary {
  overflow: hidden;
  color: #8b96a6;
  font-size: calc(11px + var(--app-font-size-offset));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.subagent-cluster-live-meta {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #8a96a8;
  font-size: calc(10px + var(--app-font-size-offset));
  white-space: nowrap;
}

.subagent-cluster-elapsed {
  border: 1px solid rgba(84, 111, 150, 0.12);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.66);
  padding: 3px 7px;
}

.subagent-cluster-list {
  display: grid;
  gap: 8px;
}

.subagent-cluster-row {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  overflow: hidden;
  border: 1px solid rgba(89, 109, 137, 0.08);
  border-radius: 14px;
  background: rgba(246, 248, 251, 0.88);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  padding: 10px 12px 9px;
  color: inherit;
  cursor: pointer;
  text-align: left;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.subagent-cluster-row:hover {
  border-color: rgba(22, 119, 255, 0.24);
  background: rgba(241, 247, 255, 0.98);
  transform: translateY(-1px);
}

.subagent-cluster-row:focus-visible {
  outline: 2px solid rgba(22, 119, 255, 0.38);
  outline-offset: 2px;
}

.subagent-cluster-row.starting,
.subagent-cluster-row.working {
  border-color: rgba(22, 119, 255, 0.14);
  background: linear-gradient(105deg, rgba(241, 247, 255, 0.96), rgba(249, 251, 254, 0.92));
}

.subagent-cluster-avatar {
  position: relative;
  display: block;
  width: 38px;
  height: 38px;
  overflow: hidden;
  border-radius: 50%;
  background: #edf3fb;
  box-shadow: 0 4px 12px rgba(36, 68, 109, 0.12), 0 0 0 1px rgba(83, 111, 151, 0.08);
}

.subagent-cluster-avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.subagent-cluster-row-main {
  min-width: 0;
}

.subagent-cluster-identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
}

.subagent-cluster-name {
  color: var(--text-primary-soft);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.subagent-cluster-profession {
  color: var(--text-subtle);
}

.subagent-cluster-stage {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #6682a8;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 16px;
}

.subagent-cluster-stage > i {
  display: inline-grid;
  width: 13px;
  height: 13px;
  place-items: center;
  border: 1px solid rgba(85, 130, 190, 0.32);
  border-radius: 50%;
  color: #4f85ca;
  font-size: calc(8px + var(--app-font-size-offset));
  font-style: normal;
  font-weight: 700;
  line-height: 1;
}

.subagent-cluster-row.starting .subagent-cluster-stage > i::after,
.subagent-cluster-row.working .subagent-cluster-stage > i::after {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #5b91d8;
  box-shadow: 0 0 0 3px rgba(91, 145, 216, 0.12);
  content: "";
}

.subagent-cluster-row.completed .subagent-cluster-stage,
.subagent-cluster-row.completed .subagent-cluster-stage > i {
  color: #4b9378;
}

.subagent-cluster-row.completed .subagent-cluster-stage > i {
  border-color: rgba(75, 147, 120, 0.35);
}

.subagent-cluster-row.failed .subagent-cluster-stage,
.subagent-cluster-row.failed .subagent-cluster-stage > i {
  color: #c35d5d;
}

.subagent-cluster-row.interrupted .subagent-cluster-stage,
.subagent-cluster-row.interrupted .subagent-cluster-stage > i {
  color: #b68a3f;
}

.subagent-cluster-index {
  margin-left: auto;
  color: rgba(73, 93, 121, 0.42);
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: calc(10px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
}

.subagent-cluster-task {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 5px;
  margin-top: 4px;
  color: #687385;
  font-size: calc(11.5px + var(--app-font-size-offset));
  line-height: 17px;
}

.subagent-cluster-task > i {
  width: 12px;
  height: 9px;
  flex: 0 0 auto;
  margin-top: 1px;
  border-bottom: 1px solid #c3ccd8;
  border-left: 1px solid #c3ccd8;
  border-radius: 0 0 0 4px;
}

.subagent-cluster-task > span {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.subagent-cluster-progress {
  display: grid;
  grid-template-columns: auto minmax(80px, 132px);
  align-items: center;
  justify-content: end;
  gap: 7px;
  margin-top: 7px;
  color: #a0a9b6;
  font-size: calc(9px + var(--app-font-size-offset));
}

.subagent-cluster-progress-track {
  display: grid;
  grid-template-columns: repeat(12, minmax(3px, 1fr));
  gap: 3px;
}

.subagent-cluster-progress-track > i {
  height: 4px;
  border-radius: 999px;
  background: rgba(100, 121, 150, 0.11);
}

.subagent-cluster-progress-track > i.filled {
  background: linear-gradient(90deg, #80aee8, #5e91d4);
}

.subagent-cluster-row.completed .subagent-cluster-progress-track > i.filled {
  background: #66ad92;
}

.subagent-cluster-row.failed .subagent-cluster-progress-track > i.filled {
  background: #d77a7a;
}

.subagent-cluster-row.interrupted .subagent-cluster-progress-track > i.filled {
  background: #d2aa5e;
}

.subagent-cluster-progress-track > i.current {
  background: #8db8ec;
  animation: subagent-progress-pulse 1.3s ease-in-out infinite;
}

@keyframes subagent-progress-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scaleY(0.9);
  }

  50% {
    opacity: 1;
    transform: scaleY(1.5);
  }
}

@media (max-width: 760px) {
  .subagent-cluster {
    border-radius: 17px;
    padding: 8px;
  }

  .subagent-cluster-header {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .subagent-cluster-live-meta {
    grid-column: 2 / -1;
    justify-self: start;
  }

  .subagent-cluster-row {
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 9px;
    padding: 9px 10px 8px;
  }

  .subagent-cluster-avatar {
    width: 36px;
    height: 36px;
  }
}

@media (max-width: 520px) {
  .subagent-cluster-summary {
    display: none;
  }

  .subagent-cluster-header {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .subagent-cluster-live-meta {
    grid-column: 1 / -1;
  }

  .subagent-cluster-progress {
    grid-template-columns: auto minmax(72px, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .subagent-cluster-row,
  .subagent-process-update.running .subagent-process-marker::before,
  .subagent-cluster-progress-track > i.current,
  .question-answer-workflow-steps > li.running .question-answer-workflow-marker > i,
  .thinking-dots i {
    animation: none;
    transition: none;
  }
}

.thinking-bubble {
