  align-items: center;
  justify-items: center;
}

.media-generation-dot-grid.image {
  aspect-ratio: 1.2;
  grid-template-columns: repeat(28, minmax(0, 1fr));
  grid-template-rows: repeat(20, minmax(0, 1fr));
}

.media-generation-dot-grid.video {
