.workflow-chat-resize-handle {
  position: absolute;
  z-index: 12;
  top: 0;
  bottom: 0;
  left: 0;
  width: 12px;
  cursor: ew-resize;
  touch-action: none;
  outline: none;
}

.workflow-chat-resize-handle::after {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 1px;
  background: rgba(128, 135, 145, 0.68);
  content: "";
  opacity: 0;
  transition: opacity 0.16s ease;
}

.workflow-chat-resize-handle:hover::after,
.workflow-chat-resize-handle:focus-visible::after,
.workflow-chat-resize-handle.active::after {
  opacity: 1;
}

.workflow-chat-resize-handle:focus-visible::after {
  background: #858c96;
}

.workflow-chat-resize-handle.active {
  background: linear-gradient(90deg, rgba(128, 135, 145, 0.06), transparent);
}

.agent-panel.collapsed .workflow-chat-resize-handle,
.desktop-body.right-panel-collapsed .workflow-chat-resize-handle {
  pointer-events: none;
  opacity: 0;
}

