  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr) 88px 112px 64px;
  align-items: center;
}

.library-table-head {
  position: relative;
  padding: 0 14px 14px;
  color: var(--text-tertiary);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 20px;
}

.library-head-menu-wrap {
  position: relative;
  min-width: 0;
}

.library-table-head-button {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 4px;
  margin-left: -4px;
  border-radius: 5px;
  padding: 1px 4px;
  color: var(--text-tertiary);
  font: inherit;
  line-height: 18px;
  text-align: left;
}

.library-table-head-button:hover {
  background: #f5f7fb;
  color: #1677ff;
}

.library-table-head-button.active {
  background: var(--selection-strong);
  color: #1677ff;
}

.library-table-head-button span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.library-table-head-button svg {
