}

.library-group-filter-menu {
  position: absolute;
  top: 24px;
  left: -8px;
  z-index: 100;
  display: grid;
  width: 184px;
  max-height: 220px;
  overflow-y: auto;
  border: 1px solid rgba(17, 24, 39, 0.08);
  border-radius: 6px;
  background: var(--surface-primary);
  opacity: 1;
  padding: 6px;
  box-shadow: 0 16px 42px rgba(17, 24, 39, 0.12);
}

.library-group-filter-menu button {
  display: flex;
  height: 28px;
  min-width: 0;
  align-items: center;
  border-radius: 5px;
  background: var(--surface-primary);
  padding: 0 8px;
  color: var(--text-primary);
  font-size: calc(12px + var(--app-font-size-offset));
  text-align: left;
}

.library-group-filter-menu button span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.library-group-filter-menu button:hover {
  background: var(--surface-soft);
  color: #1677ff;
}

.library-group-filter-menu button.active {
  background: var(--selection-strong);
  color: #1677ff;
}

.library-table {
  display: grid;
}

.library-table .library-status,
.library-table .library-empty {
  grid-column: 1 / -1;
}

.library-file-row {
  position: relative;
  min-height: 64px;
  border-radius: 8px;
  padding: 0 14px;
  color: var(--text-subtle);
