  text-align: left;
  transition: background 0.15s ease;
}

.library-file-row::after {
  position: absolute;
  right: 14px;
  bottom: 0;
  left: 14px;
  height: 0;
  border-bottom: 1px solid var(--border-subtle);
  content: "";
  pointer-events: none;
}

.library-file-row:last-child::after {
  display: none;
}

.library-file-row:hover {
  background: var(--surface-hover-translucent);
}

/* Keep the highlighted light-theme hover surfaces aligned with the preview toggle. */
html:not([data-theme="dark"]) .library-file-row:not(.active):hover,
html:not([data-theme="dark"]) .library-category:not(.active):hover,
html:not([data-theme="dark"]) .my-skill-card:hover,
html:not([data-theme="dark"]) .contact-row-wrap:not(.active):hover,
html:not([data-theme="dark"]) .conversation-row-wrap:not(.active):hover {
