}

.library-file-name strong,
.library-file-name small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.library-file-name strong {
  color: var(--text-primary);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 600;
  line-height: 20px;
}

.library-file-name small {
  color: var(--text-subtle);
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 16px;
}

.library-file-thumb {
