  height: 52px;
}

.library-file-thumb img {
  width: 24px;
  height: 24px;
}

.library-file-thumb .thumb-image,
.library-file-thumb > img.thumb-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.library-video-thumb {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: linear-gradient(145deg, #334155, #0f172a);
}

.library-video-thumb-play {
  position: absolute;
  left: 50%;
  top: 50%;
  display: block;
  width: 18px;
  height: 18px;
  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.68);
  pointer-events: none;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.28);
  transform: translate(-50%, -50%);
}

.library-video-thumb-play::before {
  position: absolute;
  left: 7px;
  top: 5px;
  width: 0;
  height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 6px solid #fff;
  content: "";
}

.library-row-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding-right: 0;
}

.library-row-actions button {
  position: relative;
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 6px;
}

.library-row-actions button:hover:not(:disabled) {
  background: var(--surface-hover-translucent);
}

.library-row-actions button:disabled {
  cursor: default;
}

.library-row-actions img {
  width: 20px;
  height: 20px;
  opacity: 0.65;
}

.library-file-row:hover .library-row-actions button:not(:disabled) img {
  opacity: 1;
}

.materials-list {
  min-width: 0;
  overflow-y: auto;
  padding: 18px;
}

.result-card,
.material-card {
  display: flex;
  min-width: 0;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 12px;
}

.result-card:hover,
.material-card:hover {
  border-color: #dbeafe;
  background: #f8fbff;
}

.result-icon {
  display: grid;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  place-items: center;
  border-radius: 10px;
  background: #eff7ff;
  color: var(--text-primary);
  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 700;
}

.result-icon img {
  width: 22px;
  height: 22px;
}

.library-status {
