.question-answer-workflow-steps article {
  min-width: 0;
  border: 1px solid rgba(202, 211, 224, 0.65);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.78);
  padding: 9px 10px;
}

.question-answer-workflow-steps > li.running article {
  border-color: rgba(86, 134, 226, 0.34);
  background: linear-gradient(135deg, rgba(244, 248, 255, 0.98), rgba(255, 255, 255, 0.9));
  box-shadow: none;
}

.question-answer-workflow-steps > li.failed article {
  border-color: rgba(211, 82, 92, 0.28);
  background: rgba(255, 247, 248, 0.9);
}

.question-answer-workflow-step-head {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.question-answer-workflow-step-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: max(16px, 1.5em);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.question-answer-workflow-step-head span {
  flex: 0 0 auto;
  color: #8290a5;
  font-size: calc(9px + var(--app-font-size-offset));
  line-height: 14px;
}

.question-answer-workflow-steps > li.running .question-answer-workflow-step-head span {
  color: #4d79ca;
}

.question-answer-workflow-steps > li.failed .question-answer-workflow-step-head span {
  color: #bf4c57;
}

.question-answer-workflow-steps p {
  margin: 4px 0 0;
  color: var(--text-subtle);
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 16px;
  overflow-wrap: anywhere;
}

@keyframes question-answer-progress-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.82);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

.subagent-panel-board {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}

.subagent-output-area {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1;
}

.subagent-panel-tabs {
  display: flex;
  flex-shrink: 0;
  gap: 12px;
  overflow-x: auto;
  border-bottom: 1px solid rgba(229, 231, 235, 0.72);
  padding: 10px 14px 9px;
  scrollbar-width: none;
}

.subagent-panel-tabs::-webkit-scrollbar {
  display: none;
}

.subagent-panel-tab {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  padding: 0;
  cursor: pointer;
  transition: transform 0.16s ease;
}

.subagent-panel-tab:hover {
  background: transparent;
  transform: translateY(-1px);
}

.subagent-panel-tab.active {
  background: transparent;
  box-shadow: none;
}

.subagent-panel-tab img {
  display: block;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  filter: saturate(0.55) brightness(1.08);
  object-fit: cover;
  opacity: 0.38;
  transition: filter 0.16s ease, opacity 0.16s ease, transform 0.16s ease;
}

.subagent-panel-tab:hover img {
  filter: saturate(0.8) brightness(1.04);
  opacity: 0.72;
}

.subagent-panel-tab.active img {
  filter: none;
  opacity: 1;
}

.subagent-output-workflow {
  --subagent-output-scrollbar-width: 0px;
  min-width: 0;
  min-height: 0;
  padding: 12px calc(12px - var(--subagent-output-scrollbar-width)) 22px 12px;
}

html:not(.window-maximized) body.desktop-app-window-mode .desktop-body:not(.right-panel-collapsed) > .agent-panel .workflow-scroll-bottom-button {
  right: calc(var(--message-scroll-bottom-gap) + var(--window-resize-hit-zone));
}

.subagent-output-panel {
  min-height: 100%;
}

.subagent-output-panel[hidden] {
  display: none;
}

.subagent-output-stream {
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  gap: 12px;
}

.subagent-output-message {
  width: 100%;
  padding-bottom: 14px;
}

.subagent-output-identity {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: baseline;
  margin: 0 4px 5px;
  color: var(--text-subtle);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 18px;
}

.subagent-output-name {
  color: var(--text-secondary);
}

.subagent-output-profession {
  color: var(--text-subtle);
}

.subagent-output-bubble {
  font-size: calc(12px + var(--app-font-size-offset));
}

.subagent-process-update {
  display: grid;
  width: 100%;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: stretch;
  gap: 8px;
  padding: 0 3px;
}

.subagent-process-marker {
  position: relative;
  display: block;
  min-height: 42px;
}

.subagent-process-marker::before {
  position: absolute;
  top: 15px;
  left: 5px;
  width: 8px;
  height: 8px;
  border: 2px solid transparent;
  border-radius: 50%;
  content: "";
}

.subagent-process-marker::after {
  position: absolute;
  top: 27px;
  bottom: -13px;
  left: 8px;
  width: 1px;
  content: "";
}

.subagent-process-update:last-child .subagent-process-marker::after {
  content: none;
}

.subagent-process-update.running .subagent-process-marker::before {
  animation: subagent-process-pulse 1.8s ease-in-out infinite;
}

.subagent-process-body {
  min-width: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 8px 10px 9px;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  transition: border-color 140ms ease, background-color 140ms ease;
}

.subagent-process-head {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 2px;
  font-size: calc(10px + var(--app-font-size-offset));
  font-weight: 600;
}

.subagent-process-head time {
  flex: 0 0 auto;
  font-size: calc(9px + var(--app-font-size-offset));
  font-weight: 400;
}

.subagent-process-text {
  overflow-wrap: anywhere;
}

.subagent-process-body .turn-result-toggle {
  margin: 0 0 8px;
}

@keyframes subagent-process-pulse {
  0%, 100% {
    transform: scale(0.82);
    opacity: 0.62;
  }
  50% {
    transform: scale(1);
    opacity: 1;
  }
}

.subagent-output-message:hover .subagent-output-actions,
.subagent-output-message:focus-within .subagent-output-actions,
.subagent-output-actions:hover {
  opacity: 1;
}

.subagent-output-bubble .message-source-link,
.subagent-output-bubble .message-inline-code,
.subagent-output-bubble .message-local-path {
  font-size: calc(10px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-source-link::before {
  font-size: calc(6px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-table {
  font-size: calc(11px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-code-head,
.subagent-output-bubble .message-prompt-text-head {
  font-size: calc(10px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-code-block code,
.subagent-output-bubble .message-prompt-text code {
  font-size: calc(10.5px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-code-copy {
  font-size: calc(9px + var(--app-font-size-offset));
}

.subagent-output-bubble .message-code-block,
.subagent-output-bubble .message-prompt-text {
  max-width: 100%;
  margin: 10px 0;
}

.subagent-output-empty {
  display: flex;
  min-height: 210px;
  align-items: center;
  justify-content: center;
  padding: 28px 16px;
  color: var(--text-muted);
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  text-align: center;
}

.workflow-empty,
.task-summary {
  border: 1px solid rgba(17, 24, 39, 0.06);
  border-radius: 10px;
  background: var(--surface-primary);
  padding: 12px 14px;
  color: var(--text-tertiary);
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  box-shadow: none;
}

.task-summary strong,
.task-summary span {
  display: block;
}

.task-summary strong {
  margin-bottom: 4px;
  color: var(--text-primary);
  font-size: calc(13px + var(--app-font-size-offset));
}

.task-summary .progress {
  margin-top: 12px;
  border-radius: 999px;
}

.timeline {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.agent-status-board {
  display: grid;
  gap: 14px;
}

.agent-status-summary {
  display: grid;
  gap: 3px;
  border: 1px solid rgba(17, 24, 39, 0.06);
  border-radius: 8px;
  background: var(--surface-primary);
  padding: 12px 13px;
  box-shadow: none;
}

.agent-status-summary strong {
  color: var(--text-primary);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 18px;
}

.agent-status-summary span {
  color: #8d95a1;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 17px;
}

.timeline li {
  position: relative;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 10px;
  padding-bottom: 18px;
}

.timeline li:last-child {
  padding-bottom: 0;
}

.timeline-rail {
  position: relative;
  display: flex;
  width: 18px;
  flex-shrink: 0;
  justify-content: center;
}

.timeline-rail::before {
  position: relative;
  z-index: 1;
  display: block;
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border: 3px solid #fff;
  border-radius: 50%;
  background: #d1d5db;
  box-shadow: 0 0 0 1px #d8dbe1;
  content: "";
}

.timeline-rail i {
  position: absolute;
  left: 50%;
  top: 18px;
  width: 1px;
  height: calc(100% + 2px);
  background: #edf0f3;
  transform: translateX(-50%);
}

.timeline li.running .timeline-rail::before {
  background: var(--control-primary);
  box-shadow: 0 0 0 1px #111827;
}

.timeline li.completed .timeline-rail::before {
  background: #17a34a;
  box-shadow: 0 0 0 1px #17a34a;
}

.timeline li.failed .timeline-rail::before {
  background: #f04438;
  box-shadow: 0 0 0 1px #f04438;
}

.timeline li.pending_external .timeline-rail::before {
  background: #f59e0b;
  box-shadow: 0 0 0 1px #f59e0b;
}

.timeline-card {
  min-width: 0;
  border-bottom: 1px solid rgba(17, 24, 39, 0.06);
  padding: 0 0 15px;
}

.agent-status-card {
  border: 1px solid rgba(17, 24, 39, 0.07);
  border-radius: 8px;
  background: var(--surface-primary);
  padding: 0;
  box-shadow: none;
}

.agent-status-card[open] {
  border-color: var(--border-translucent);
}

.timeline li:last-child .timeline-card {
  border-bottom: 1px solid rgba(17, 24, 39, 0.07);
  padding-bottom: 0;
}

.timeline-head {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 8px;
}

.agent-status-card .timeline-head {
  min-height: 54px;
  align-items: center;
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 10px 11px;
  cursor: pointer;
  list-style: none;
}

.agent-status-card .timeline-head::-webkit-details-marker {
  display: none;
}

.agent-status-card .timeline-head::before {
  align-self: center;
  color: var(--text-muted);
  content: "›";
  font-size: calc(16px + var(--app-font-size-offset));
  line-height: 1;
  transform: rotate(0deg);
  transition: transform 0.16s ease;
}

.agent-status-card[open] .timeline-head::before {
  transform: rotate(90deg);
}

.agent-step-copy {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.timeline strong {
  display: inline;
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 18px;
  overflow-wrap: anywhere;
}

.timeline strong span {
  color: var(--text-subtle);
}

.timeline small {
  display: block;
  margin-top: 4px;
  color: #8d95a1;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 17px;
  overflow-wrap: anywhere;
}

.agent-status-card .timeline small {
  margin-top: 0;
}

.agent-step-detail {
  display: grid;
  gap: 9px;
  border-top: 1px solid rgba(17, 24, 39, 0.06);
  padding: 10px 11px 11px;
}

.agent-step-detail-row {
  display: grid;
  gap: 5px;
}

.agent-step-detail-row span,
.agent-step-meta span,
.agent-step-empty {
  color: #8d95a1;
  font-size: calc(10px + var(--app-font-size-offset));
  font-weight: 600;
  line-height: 14px;
}

.agent-step-detail-row pre {
  max-height: 210px;
  overflow: auto;
  margin: 0;
  border-radius: 6px;
  background: #f7f8fa;
  padding: 8px 9px;
  color: var(--text-secondary-strong);
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 16px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.timeline em {
  display: inline-flex;
  min-width: 0;
  max-width: 64px;
  height: 18px;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 999px;
  background: var(--surface-hover);
  padding: 0 7px;
  color: var(--text-subtle);
  font-size: calc(10px + var(--app-font-size-offset));
  font-style: normal;
  font-weight: 700;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.timeline em.completed {
  background: #ecfdf5;
  color: #16a34a;
}

.timeline em.pending {
  background: var(--surface-hover);
  color: var(--text-subtle);
}

.timeline em.running {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.timeline em.failed {
  background: #fff1f1;
  color: #ef4444;
}

.timeline em.pending_external {
  background: #fff7ed;
  color: #d97706;
}

.profile-menu {
  position: fixed;
  left: 15px;
  top: 44px;
  z-index: 50;
  box-sizing: border-box;
  width: min(360px, calc(100vw - 30px));
  border: 1px solid rgba(17, 24, 39, 0.06);
  border-radius: 20px;
  background: var(--surface-primary);
  padding: 22px 18px 18px;
  box-shadow: 0 14px 38px rgba(17, 24, 39, 0.12);
}

.popover-backdrop {
  position: fixed;
  inset: 0;
  z-index: 40;
}

.profile-head {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 58px;
  margin-bottom: 24px;
}

.profile-head img {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  object-fit: cover;
}

.profile-head-copy {
  min-width: 0;
  flex: 1;
}

.profile-name-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
}

.profile-name-row > strong {
  flex: 1 1 auto;
}

.profile-head strong,
.profile-head span {
  display: block;
}

.profile-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: calc(16px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-head span {
  margin-top: 2px;
  color: var(--text-subtle);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 16px;
}

.membership-badge {
  box-sizing: border-box;
  display: inline-flex;
  width: max-content;
  height: 20px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 0 7px;
  font-size: calc(10px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 18px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.membership-badge-experience {
  border-color: #d9dde4;
  background: #f1f2f4;
  color: #717986;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.membership-badge-member {
  border-color: rgba(190, 104, 8, 0.42);
  background: linear-gradient(135deg, #f3a52f 0%, #ffd77c 50%, #e9891c 100%);
  color: #6d3700;
  box-shadow:
    inset 0 1px 0 rgba(255, 248, 219, 0.8),
    0 2px 5px rgba(190, 104, 8, 0.2);
}

.profile-head .profile-membership-badge {
  display: inline-flex;
  margin-top: 0;
  color: #6d3700;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 18px;
}

.profile-head .profile-membership-badge.membership-badge-experience {
  color: #717986;
}

.profile-stats {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  row-gap: 0;
  margin-bottom: 0;
}

.profile-level-row,
.profile-token-row,
.profile-subscription-row {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: 104px minmax(0, 1fr);
  align-items: center;
  column-gap: 18px;
  min-height: 42px;
  color: var(--text-primary);
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 20px;
}

.profile-level-row > span,
.profile-token-row > span,
.profile-subscription-label {
  align-self: center;
}

.profile-level-row strong {
  display: flex;
  min-width: 0;
  min-height: 42px;
  align-items: center;
  justify-content: flex-start;
  overflow: hidden;
  font-size: calc(14px + var(--app-font-size-offset));
  line-height: 20px;
  padding-left: 0;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-level-icons {
  display: flex;
  max-width: 220px;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 4px;
  background: transparent;
}

.profile-level-icons img {
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  background: transparent;
  box-shadow: none;
  object-fit: contain;
}

img[data-level-icon="egg"] {
  transform: translateY(-1px);
}

.profile-token-row {
  min-height: 50px;
}

.profile-token-balance {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
  padding-left: 0;
}

.profile-token-row strong {
  min-width: 0;
  overflow: hidden;
  font-size: calc(15px + var(--app-font-size-offset));
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-subscription-row {
  min-height: 42px;
}

.profile-subscription-label {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  overflow-wrap: anywhere;
}

.profile-subscription-label > span {
  white-space: normal;
}

.profile-subscription-row > strong {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px 8px;
  padding-left: 0;
}

.profile-subscription-row b {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: calc(15px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: max(20px, 1.5em);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.library-home-nav-row .library-pane-title {
  height: auto;
  padding: 0;
}

.profile-subscription-row time {
  color: var(--text-subtle);
  font-size: calc(11px + var(--app-font-size-offset));
  font-style: normal;
  font-weight: 400;
  line-height: 18px;
  transform: translateY(1px);
}

.profile-recharge-button {
  box-sizing: border-box;
  display: inline-grid;
  width: auto;
  min-width: 52px;
  height: 26px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(17, 24, 39, 0.2);
  border-radius: 999px;
  background: transparent;
  color: var(--text-secondary-strong);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 600;
  line-height: 14px;
  padding: 0 11px;
  text-align: center;
  white-space: nowrap;
  appearance: none;
  transition:
    border-color 0.15s ease,
    background-color 0.15s ease,
    box-shadow 0.15s ease,
    color 0.15s ease,
    opacity 0.15s ease;
}

.profile-recharge-button:hover:not(:disabled) {
  border-color: rgba(17, 24, 39, 0.34);
  background: var(--surface-hover);
  color: var(--text-primary);
}

.profile-recharge-button:active:not(:disabled) {
  background: var(--surface-active-translucent);
  opacity: 1;
}

.profile-recharge-button:focus-visible {
  outline: 2px solid rgba(37, 99, 235, 0.34);
  outline-offset: 2px;
}

