  --recharge-details-accent: #168ee9;
  --recharge-tutorial-link: #168ee9;
  --recharge-tutorial-link-hover: #0878c9;
  --recharge-tutorial-link-active: #0566ad;
  --recharge-tutorial-link-disabled: #94a0af;
  --recharge-tutorial-link-focus: rgba(22, 142, 233, 0.32);
  --recharge-details-warning-text: #8a4b00;
  --recharge-details-warning-bg: rgba(237, 155, 22, 0.14);
  --recharge-details-warning-border: rgba(181, 103, 0, 0.28);
