  align-items: center;
  gap: 40px;
}

.recharge-payment-address-copy {
  display: grid;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--recharge-details-label);
  padding: 0;
  cursor: pointer;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease,
    transform 0.16s ease;
}

.recharge-payment-address-copy svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.recharge-payment-address-copy:hover,
.recharge-payment-address-copy.copied {
  border-color: color-mix(in srgb, var(--recharge-details-accent) 35%, transparent);
  background: color-mix(in srgb, var(--recharge-details-accent) 10%, transparent);
  color: var(--recharge-details-accent);
}

.recharge-payment-address-copy:active {
  transform: scale(0.94);
}

.recharge-payment-address-copy:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--recharge-details-accent) 72%, transparent);
  outline-offset: 2px;
}

.recharge-payment-underpaid {
  display: grid;
  margin: -10px 0 0 94px;
  gap: 4px;
  border: 1px solid var(--recharge-details-warning-border);
