  background: var(--recharge-details-warning-bg);
  padding: 10px 12px;
  color: var(--recharge-details-label);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 1.5;
}

.recharge-payment-underpaid strong {
  color: var(--recharge-details-warning-text);
  font-weight: 750;
}

.recharge-payment-details-main.internal-transfer {
  grid-template-columns: minmax(0, 1fr) minmax(210px, 260px);
  gap: clamp(34px, 5vw, 80px);
}

.recharge-payment-internal-steps {
  display: grid;
  min-width: 0;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.recharge-payment-internal-step {
  display: grid;
  min-width: 0;
  grid-template-columns: 30px 84px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}

.recharge-payment-step-number {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid var(--recharge-details-border);
  border-radius: 50%;
  color: var(--recharge-details-label);
  font-size: calc(12px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
}

.recharge-payment-step-label {
  color: var(--recharge-details-label);
  font-size: calc(14px + var(--app-font-size-offset));
  white-space: nowrap;
}

.recharge-payment-internal-field {
  display: flex;
  min-width: 0;
  min-height: 64px;
  align-items: center;
  gap: 12px;
  border: 1px solid var(--recharge-internal-field-border);
  border-radius: 12px;
  background: var(--recharge-internal-field-bg);
  padding: 10px 14px 10px 18px;
}

.recharge-payment-internal-field code {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--recharge-details-text);
  font-family: inherit;
  font-size: calc(17px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 650;
}

.recharge-payment-internal-field.amount strong {
  display: inline-flex;
  min-width: max-content;
  align-items: baseline;
  gap: 5px;
  color: var(--recharge-internal-amount);
  font-size: calc(20px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 720;
}

.recharge-payment-internal-field.amount small {
  color: var(--recharge-details-text);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 540;
}

.recharge-payment-exact-badge {
  margin-left: auto;
  border-radius: 6px;
  background: var(--recharge-internal-badge-bg);
  padding: 4px 8px;
  color: var(--recharge-internal-badge-text);
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 1.2;
  white-space: nowrap;
}

.recharge-payment-internal-status {
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 12px;
}

.recharge-payment-internal-logo {
  display: grid;
  width: 56px;
  height: 56px;
  place-items: center;
}

.recharge-payment-internal-logo .trading-market-asset-logo {
  width: 52px;
  height: 52px;
  flex-basis: 52px;
  animation: none;
  transition: none;
}

.recharge-payment-internal-logo .recharge-payment-binance-logo {
  width: 52px;
  height: 52px;
  flex-basis: 52px;
}

.recharge-payment-internal-logo .recharge-payment-exchange-logo {
  width: 52px;
  height: 52px;
  flex-basis: 52px;
}

.recharge-payment-internal-logo .recharge-payment-exchange-logo svg {
  width: 34px;
  height: 34px;
}

.recharge-payment-internal-status > p {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin: 0;
  color: var(--recharge-details-label);
  font-size: calc(12px + var(--app-font-size-offset));
}

.recharge-payment-internal-status > p strong {
  color: var(--recharge-details-text);
  font-size: calc(25px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 540;
  line-height: 1;
}

.recharge-payment-internal-status > p small {
  color: var(--recharge-details-text);
  font-size: calc(12px + var(--app-font-size-offset));
}

.recharge-payment-internal-detecting {
  display: inline-flex;
  min-width: 192px;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 12px;
  background: var(--recharge-internal-status-bg);
  color: var(--recharge-internal-status-text);
  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 650;
}

.recharge-payment-internal-detecting svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.6;
  animation: recharge-payment-spin 1.6s linear infinite;
}

.recharge-payment-internal-countdown {
  color: var(--recharge-details-label);
  font-size: calc(11px + var(--app-font-size-offset));
}

.recharge-payment-internal-countdown time {
  font-variant-numeric: tabular-nums;
}

.recharge-payment-qr-column {
  display: grid;
  align-content: center;
  justify-items: end;
  gap: 12px;
}

.recharge-payment-qr-column > .recharge-payment-internal-countdown {
  width: 194px;
  text-align: center;
}

.recharge-payment-qr-frame {
  position: relative;
  display: grid;
  width: 194px;
  height: 194px;
  place-items: center;
  overflow: hidden;
  border: 1px solid #d9dee6;
  border-radius: 13px;
  background: #ffffff;
  padding: 10px;
  box-shadow: 0 8px 22px rgba(29, 45, 67, 0.07);
}

.recharge-payment-qr-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.recharge-payment-qr-image[hidden] {
  display: none;
}

.recharge-payment-qr-logo {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 4px solid #ffffff;
  border-radius: 11px;
  background: #ffffff;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.16);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.88);
  animation: none;
  transition: none;
}

.recharge-payment-qr-logo .trading-market-asset-logo {
  width: 30px;
  height: 30px;
  flex-basis: 30px;
  animation: none;
  transition: none;
}

.recharge-payment-qr-logo .recharge-payment-binance-logo {
  width: 30px;
  height: 30px;
  flex-basis: 30px;
}

.recharge-payment-qr-frame.loaded .recharge-payment-qr-logo {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.recharge-payment-qr-loading {
  display: none;
  color: var(--recharge-details-muted);
  font-size: calc(11px + var(--app-font-size-offset));
}

.recharge-payment-qr-frame.loading .recharge-payment-qr-loading,
.recharge-payment-qr-frame.error .recharge-payment-qr-loading {
  display: block;
}

.recharge-payment-qr-frame.loading::before {
  position: absolute;
  top: 66px;
  width: 24px;
  height: 24px;
  border: 2px solid rgba(47, 155, 255, 0.18);
  border-top-color: #2f9bff;
  border-radius: 50%;
  content: "";
  animation: recharge-payment-spin 0.8s linear infinite;
}

.recharge-payment-qr-frame.error .recharge-payment-qr-loading {
  font-size: 0;
}

.recharge-payment-qr-frame.error .recharge-payment-qr-loading::after {
  color: #d95757;
  content: var(--i18n-qr-generation-failed);
  font-size: calc(11px + var(--app-font-size-offset));
}

.recharge-payment-agreement {
  grid-column: 1 / -1;
  margin: -4px 0 0;
  color: var(--recharge-details-label);
  font-size: calc(12px + var(--app-font-size-offset));
