    opacity 0.16s ease,
    transform 0.16s ease;
}

.recharge-payment-tutorial-link:hover:not(:disabled) {
  color: var(--recharge-tutorial-link-hover);
  text-decoration: underline;
}

.recharge-payment-tutorial-link:active:not(:disabled) {
  color: var(--recharge-tutorial-link-active);
  transform: translateY(1px);
}

.recharge-payment-tutorial-link:focus-visible {
  outline: 2px solid var(--recharge-tutorial-link-focus);
  outline-offset: 2px;
}

.recharge-payment-tutorial-link:disabled {
  color: var(--recharge-tutorial-link-disabled);
  text-decoration: none;
  cursor: not-allowed;
  opacity: 0.7;
  transform: none;
}

.recharge-payment-state {
  display: flex;
  min-height: 240px;
  grid-column: 1 / -1;
  align-items: center;
  justify-content: center;
  gap: 16px;
  color: var(--recharge-details-text);
  text-align: left;
}

.recharge-payment-state-icon {
  display: inline-flex;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--recharge-details-accent) 24%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--recharge-details-accent) 10%, transparent);
  color: var(--recharge-details-accent);
}

.recharge-payment-state-icon svg {
  width: 25px;
  height: 25px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.recharge-payment-state-icon svg.spin {
  animation: recharge-payment-spin 1.1s linear infinite;
}

.recharge-payment-state > div {
  max-width: 520px;
}

.recharge-payment-state strong {
  display: block;
  font-size: calc(17px + var(--app-font-size-offset));
}

.recharge-payment-state p {
  margin: 6px 0 0;
  color: var(--recharge-details-muted);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 1.55;
}

.recharge-payment-state button {
  min-height: 36px;
  border: 1px solid color-mix(in srgb, var(--recharge-details-accent) 34%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--recharge-details-accent) 10%, transparent);
  padding: 0 15px;
  color: var(--recharge-details-accent);
  cursor: pointer;
  font: inherit;
  font-weight: 650;
}

.recharge-payment-state button:hover {
  border-color: color-mix(in srgb, var(--recharge-details-accent) 58%, transparent);
  background: color-mix(in srgb, var(--recharge-details-accent) 16%, transparent);
}

.recharge-payment-state button:active {
  transform: translateY(1px);
}

.recharge-payment-state button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--recharge-details-accent) 72%, transparent);
  outline-offset: 2px;
}

.recharge-payment-state.paid .recharge-payment-state-icon {
  border-color: rgba(30, 166, 110, 0.3);
  background: rgba(30, 166, 110, 0.11);
  color: #14875e;
}

.recharge-payment-state.error .recharge-payment-state-icon,
.recharge-payment-state.expired .recharge-payment-state-icon {
  border-color: rgba(211, 77, 77, 0.28);
  background: rgba(211, 77, 77, 0.09);
  color: #c24141;
}

.recharge-payment-state.manual .recharge-payment-state-icon {
  border-color: rgba(205, 139, 24, 0.3);
  background: rgba(205, 139, 24, 0.1);
  color: #a96e0c;
}

@keyframes recharge-payment-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .recharge-payment-qr-frame.loading::before,
  .recharge-payment-internal-detecting svg,
  .recharge-payment-state-icon svg.spin {
    animation: none;
  }
}

