}

.composer-prompt-favorite-row {
  display: flex;
  min-width: 0;
  align-items: center;
  border-radius: 6px;
}

.composer-prompt-favorite-row:hover,
.composer-prompt-favorite-row.active {
  background: var(--surface-soft);
}

.composer-skill-popover .composer-prompt-favorite-main {
  min-width: 0;
  min-height: 42px;
  flex: 1 1 auto;
  gap: 0;
  padding: 7px 8px 7px 10px;
  background: transparent;
  font-size: calc(13px + var(--app-font-size-offset));
}

.composer-skill-popover .composer-prompt-favorite-main:hover,
.composer-skill-popover .composer-prompt-favorite-main.active {
  background: transparent;
}

.composer-prompt-favorite-main span {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.composer-skill-popover .composer-prompt-favorite-edit {
  width: auto;
  min-width: 62px;
  min-height: 42px;
  flex: 0 0 auto;
  justify-content: flex-end;
  gap: 0;
  padding: 7px 9px 7px 3px;
  background: transparent;
  color: var(--brand-blue);
  font-size: calc(12px + var(--app-font-size-offset));
  white-space: nowrap;
}

.composer-skill-popover .composer-prompt-favorite-edit:hover {
  background: transparent;
  color: var(--brand-blue);
}

.composer-skill-popover .composer-prompt-favorite-edit > span {
  color: var(--brand-blue);
  font-weight: 500;
}

.composer-prompt-favorite-status {
  display: grid;
  min-height: 84px;
  place-items: center;
  gap: 8px;
  padding: 14px;
