@media (max-width: 720px) {}

@media (max-width: 1280px) {
  .recharge-product-grid {
    grid-template-columns: repeat(2, minmax(210px, 1fr));
  }
}

@media (max-width: 860px) {
  .recharge-page-scroll {
    padding-inline: 20px;
  }

  .recharge-page-intro {
    grid-template-columns: 1fr;
    justify-items: center;
  }

  .recharge-page-intro > div:first-child {
    grid-column: 1;
    grid-row: 1;
    justify-self: center;
  }

  .recharge-page-intro > .recharge-page-balances {
    grid-column: 1;
    grid-row: 2;
    justify-content: center;
    justify-self: stretch;
  }

  .recharge-history-action {
    grid-column: 1;
    grid-row: 3;
    justify-self: center;
  }

  .recharge-product-grid {
    width: 100%;
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .recharge-product-card {
    min-height: 0;
  }
}

@media (max-width: 720px) {
  .recharge-history-overlay { padding: 16px; }
  .recharge-history-dialog { width: calc(100vw - 32px); height: calc(100vh - 64px); max-height: calc(100vh - 64px); border-radius: 16px; }
  .recharge-history-dialog > header { padding-inline: 18px 14px; }
  .recharge-history-body { padding-inline: 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .recharge-support-button,
  .recharge-history-button { transition: none; }
  .recharge-history-skeleton::after { animation: none; }
}

@media (max-width: 760px) {
  .recharge-payment-shell {
    margin-top: 12px;
  }

  .recharge-payment-methods {
    height: auto;
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .recharge-payment-network-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .recharge-payment-details {
    padding-inline: 24px;
  }

  .recharge-payment-details-main,
  .recharge-payment-details-main.internal-transfer {
    grid-template-columns: 1fr;
  }

  .recharge-payment-qr-column {
    justify-items: center;
  }

}

@media (max-width: 520px) {
  .recharge-page-balance {
    justify-content: center;
  }

  .recharge-payment-methods {
    padding: 18px 16px;
  }

  .recharge-payment-details {
    padding: 22px 16px 18px;
  }

  .recharge-payment-internal-step {
    grid-template-columns: 28px minmax(0, 1fr);
  }

  .recharge-payment-step-label {
    grid-column: 2;
  }

  .recharge-payment-internal-field {
    grid-column: 1 / -1;
  }

  .recharge-payment-internal-field.amount {
    flex-wrap: wrap;
  }

  .recharge-payment-exact-badge {
    order: 3;
    margin-left: 0;
  }

  .recharge-payment-underpaid {
    margin-left: 0;
  }

}

