.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  background: rgba(17, 24, 39, 0.42);
}

.external-channel-login-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  z-index: 90;
  width: min(360px, calc(100vw - 48px));
  margin: 0;
  border: 0;
  border-radius: 12px;
  background: var(--surface-primary);
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.2);
  color: var(--text-primary);
  padding: 0;
  transform: translate(-50%, -50%);
}

.external-channel-login-dialog header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  border-bottom: 0;
  padding: 18px 18px 14px;
}

.external-channel-login-dialog h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: calc(17px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 24px;
}

.external-channel-login-dialog p {
  margin: 4px 0 0;
  color: var(--text-subtle);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
}

.external-channel-login-dialog section {
  display: grid;
  justify-items: center;
  gap: 12px;
  padding: 20px 22px 24px;
}

.external-channel-qr-frame {
  display: grid;
  width: 210px;
  height: 210px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface-primary);
  padding: 10px;
}

.external-channel-qr-image {
  display: block;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.external-channel-qr-placeholder,
.external-channel-qr-error {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  border-radius: 6px;
  background: var(--surface-cool);
  color: var(--text-subtle);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 19px;
  text-align: center;
}

.external-channel-qr-error {
  color: #b42318;
  background: #fff1f0;
  padding: 14px;
}

.external-channel-login-state {
  color: var(--text-secondary);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 19px;
  text-align: center;
}

.external-channel-login-state.connected {
  color: #15803d;
}

.external-channel-login-state.error,
.external-channel-login-state.expired {
  color: #b42318;
}

.telegram-channel-login-dialog {
  box-sizing: border-box;
