  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 20px;
}

.settings-theme-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.settings-theme-options {
  display: grid;
  width: 196px;
  height: 36px;
  flex: 0 0 auto;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: center;
  gap: 2px;
  border: 1px solid #dde1e7;
  border-radius: 10px;
  background: #eef0f3;
  padding: 3px;
}

.settings-theme-option {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 28px;
  border: 1px solid transparent;
  border-radius: 7px;
  color: #646d79;
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  transition: background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, color 0.16s ease;
}

.settings-theme-option > span {
  display: inline-block;
  transform: translateY(-1px);
}

.settings-theme-icon {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.64;
  transition: color 0.16s ease, opacity 0.16s ease, transform 0.16s ease;
}

.settings-theme-option:hover:not(.active) {
  background: rgba(255, 255, 255, 0.5);
  color: var(--text-primary);
}

.settings-theme-option.active {
  border-color: #d9dee7;
  background: #fff;
  color: var(--text-primary);
  font-weight: 500;
  box-shadow: 0 2px 5px rgba(17, 24, 39, 0.16), 0 0 0 1px rgba(17, 24, 39, 0.04);
}

.settings-theme-option.active .settings-theme-icon {
  opacity: 1;
  transform: scale(1.06);
}

.settings-theme-option[data-settings-theme="light"].active .settings-theme-icon {
  color: #646d79;
  opacity: 0.64;
}

.settings-theme-option:focus-visible {
  outline: 2px solid rgba(22, 119, 255, 0.34);
  outline-offset: 1px;
}

.settings-font-size-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.settings-font-size-row > span {
  padding-top: 1px;
}

.settings-font-size-options {
  position: relative;
  display: grid;
  width: 224px;
  flex: 0 0 auto;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-left: auto;
  transform: translateX(12.5%);
}

.settings-font-size-options::before {
  position: absolute;
  left: 12.5%;
  right: 12.5%;
  top: 8px;
  height: 1px;
  background: var(--line-strong);
  content: "";
}

.settings-font-size-option {
  position: relative;
  z-index: 1;
  display: grid;
  min-width: 44px;
  min-height: 42px;
  grid-template-rows: 17px 20px;
  justify-items: center;
  align-items: start;
  padding: 0;
  color: var(--text-secondary);
}

.settings-font-size-node {
  display: block;
  width: 1px;
  height: 5px;
  margin-top: 3px;
  background: var(--text-tertiary);
  transition: width 0.14s ease, height 0.14s ease, margin 0.14s ease, border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.settings-font-size-label {
  color: var(--text-secondary);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
}

.settings-font-size-label.empty {
  visibility: hidden;
}

.settings-font-size-option.active .settings-font-size-node {
  width: 17px;
  height: 17px;
  margin-top: 0;
  border: 2px solid var(--surface-primary);
  border-radius: 50%;
  background: var(--text-primary);
  box-shadow: 0 0 0 1px rgba(17, 24, 39, 0.08), 0 1px 4px rgba(17, 24, 39, 0.32);
}

.settings-font-size-option.active .settings-font-size-label {
  color: var(--text-primary);
  font-weight: 500;
}

.settings-font-size-option:focus-visible {
  outline: 2px solid rgba(22, 119, 255, 0.34);
  outline-offset: 2px;
  border-radius: 6px;
}

.settings-switch {
  position: relative;
  width: 36px;
  height: 20px;
  flex: 0 0 auto;
  border-radius: 999px;
  background: #d7d8da;
  transition: background 0.16s ease, opacity 0.16s ease;
}

.settings-switch::before {
  position: absolute;
  left: 3px;
  top: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--surface-primary);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
  content: "";
  transition: transform 0.16s ease;
}

.settings-switch.active {
  background: var(--control-primary);
}

.settings-switch.active::before {
  transform: translateX(16px);
}

.settings-switch:disabled {
  cursor: default;
  opacity: 0.68;
}

.settings-storage-row {
