  gap: 24px;
}

.haolo-select {
  position: relative;
  display: inline-flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  flex: 0 0 auto;
}

.haolo-select-sr-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.haolo-select-trigger {
  display: inline-flex;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 34px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 1px solid var(--border-field);
  border-radius: 8px;
  background: var(--surface-primary);
  padding: 0 11px 0 12px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 500;
  /* Ellipsis clips both axes: reserve font-relative space for g/j/p/q/y. */
  line-height: 1.5;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease, color 0.16s ease;
}

.haolo-select-trigger > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.haolo-select-trigger svg {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
  transition: transform 0.16s ease;
}

.haolo-select-trigger:hover:not(:disabled) {
  border-color: var(--line-strong);
  background: var(--surface-subtle);
}

.haolo-select-trigger:active:not(:disabled),
.haolo-select.open .haolo-select-trigger {
  border-color: var(--brand-blue);
  background: var(--surface-hover);
}

.haolo-select.open .haolo-select-trigger svg {
  transform: rotate(180deg);
}

.haolo-select-trigger:focus-visible {
  outline: 0;
  border-color: var(--brand-blue);
  box-shadow: 0 0 0 2px rgba(22, 119, 255, 0.16);
}

.haolo-select-trigger:disabled {
  border-color: var(--border-field);
  background: var(--surface-disabled);
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: 0.7;
}

.haolo-select-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  left: 0;
  z-index: 210;
  display: block;
  max-height: 220px;
  overflow: auto;
  border: 1px solid rgba(17, 24, 39, 0.1);
  border-radius: 9px;
  background: var(--surface-primary);
  box-shadow: 0 16px 42px rgba(17, 24, 39, 0.16);
  padding: 4px;
}

.haolo-select.opens-above .haolo-select-menu {
  top: auto;
  bottom: calc(100% + 6px);
}

.haolo-select-menu[hidden] {
  display: none;
}

.haolo-select-option {
  display: block;
  width: 100%;
  min-width: 0;
  min-height: 32px;
  border-radius: 6px;
  background: transparent;
  padding: 6px 9px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: max(20px, 1.5em);
  text-align: left;
  white-space: normal;
  cursor: pointer;
}

.haolo-select-option:hover:not(:disabled),
.haolo-select-option:focus-visible {
  outline: 0;
  background: var(--surface-hover);
}

.haolo-select-option.selected,
.haolo-select-option[aria-selected="true"] {
  background: var(--selection-strong);
  color: var(--text-primary);
  font-weight: 500;
}

.haolo-select-option:active:not(:disabled) {
  background: var(--surface-active-translucent);
}

.haolo-select-option:disabled {
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: 0.58;
}

.settings-language-select {
  width: 196px;
}

.external-model-base-url-select .haolo-select-trigger {
  height: 32px;
