.approval-dialog section,
.approval-dialog form {
  display: grid;
  gap: 12px;
  padding: 18px;
}

.approval-dialog h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: calc(16px + var(--app-font-size-offset));
  line-height: 22px;
}

.approval-dialog p {
  margin: 0;
  color: var(--text-secondary);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 20px;
}

.approval-dialog pre {
  max-height: 160px;
  overflow: auto;
  border-radius: 8px;
  background: var(--surface-subtle);
  padding: 10px;
  color: var(--text-primary);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
  white-space: pre-wrap;
}

.approval-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.approval-dialog label {
  display: grid;
  gap: 7px;
  color: var(--text-secondary);
  font-size: calc(12px + var(--app-font-size-offset));
}

.approval-dialog input {
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 8px;
  outline: 0;
  padding: 0 10px;
}

.checkbox-line {
  display: flex !important;
  grid-template-columns: auto 1fr;
  align-items: center;
}

.checkbox-line input {
  width: 15px;
  height: 15px;
}

.api-state {
  margin: 0;
  border-radius: 8px;
  background: var(--surface-faint);
  padding: 9px 10px;
  color: var(--text-subtle);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
}

.api-state.live {
  background: var(--green-soft);
  color: #047857;
}

.api-state.offline {
  background: #fff7ed;
  color: #c2410c;
}

.primary-button,
.secondary-button {
  height: 36px;
  border-radius: 999px;
  padding: 0 16px;
  font-weight: 700;
}

.primary-button {
  background: var(--blue);
  color: #fff;
}

.secondary-button {
  background: var(--surface-hover);
  color: var(--text-secondary);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 22px;
  z-index: 100;
  max-width: 560px;
  border-radius: 999px;
  background: rgba(17, 24, 39, 0.92);
  padding: 10px 16px;
  color: #fff;
  font-size: calc(13px + var(--app-font-size-offset));
  transform: translateX(-50%);
}

.contact-request-sent-toast {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 120;
  display: grid;
  width: 88px;
  height: 88px;
  place-items: center;
  align-content: center;
  gap: 6px;
  border-radius: 12px;
  background: rgba(71, 71, 71, 0.88);
  color: #fff;
  box-shadow: 0 16px 42px rgba(0, 0, 0, 0.18);
  pointer-events: none;
  transform: translate(-50%, -50%);
}

.contact-request-sent-toast svg {
  width: 40px;
  height: 40px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2.4;
}

.contact-request-sent-toast strong {
  color: #fff;
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 18px;
}

@media (max-width: 1100px) {
  .desktop-shell {
    min-width: 0;
  }

  .skills-masonry {
    column-count: 4;
  }

  .auto-task-empty {
    padding-right: 32px;
    padding-left: 32px;
  }

  .auto-task-list {
    grid-template-columns: repeat(2, minmax(260px, 1fr));
    gap: 20px;
  }

  .auto-task-detail-card {
    right: 32px;
    bottom: 48px;
    left: 120px;
  }

  .auto-task-chat-card {
    right: 0;
    bottom: 0;
    left: 0;
    width: auto;
  }

  .auto-task-template-row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
  }

  .message-stack {
    max-width: min(640px, 82%);
  }
}

@media (max-width: 760px) {
  .skills-masonry {
    column-count: 2;
  }

  .auto-task-empty {
    padding-top: 64px;
  }

  .auto-task-list {
    grid-template-columns: 1fr;
  }

  .auto-task-detail-chat {
    padding-right: 24px;
    padding-left: 24px;
  }

  .auto-task-detail-card {
    right: 18px;
    bottom: 36px;
    left: 18px;
  }

  .auto-task-chat-card {
    right: 0;
    bottom: 0;
    left: 0;
    width: auto;
  }

  .auto-task-template-row {
    grid-template-columns: 1fr;
  }

  .auto-task-time-row {
    grid-template-columns: 1fr;
  }
}

/* ===== Chat UX batch: hover time + copy, markdown code blocks, headings ===== */

.message-bubble {
  position: relative;
}

.bubble-hover-bar {
  position: absolute;
  top: 100%;
  right: 2px;
  padding-top: 4px;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 1.4;
  color: #b6bcc6;
  background: transparent;
  white-space: nowrap;
  opacity: 0;
  pointer-events: auto;
  transition: opacity 0.08s ease;
  z-index: 13;
}

.message-row:hover .message-bubble:has(.message-text) .bubble-hover-bar,
.message-row:hover .message-bubble:has([data-action="edit-message"]) .bubble-hover-bar,
.message-row:hover .message-bubble:has([data-action="favorite-message"]) .bubble-hover-bar,
.message-row:hover .message-bubble:has([data-action="quote-message"]) .bubble-hover-bar,
.message-row:focus-within .message-bubble:has(.message-text) .bubble-hover-bar,
.message-row:focus-within .message-bubble:has([data-action="edit-message"]) .bubble-hover-bar,
.message-row:focus-within .message-bubble:has([data-action="favorite-message"]) .bubble-hover-bar,
.message-row:focus-within .message-bubble:has([data-action="quote-message"]) .bubble-hover-bar,
.message-bubble:has(.message-text) .bubble-hover-bar:hover,
.message-bubble:has([data-action="edit-message"]) .bubble-hover-bar:hover,
.message-bubble:has([data-action="favorite-message"]) .bubble-hover-bar:hover,
.message-bubble:has([data-action="quote-message"]) .bubble-hover-bar:hover {
  opacity: 1;
}

.bubble-time {
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 1.4;
  white-space: nowrap;
}

.bubble-copy {
  background: transparent;
  border: none;
  color: inherit;
  min-width: 0;
  height: auto;
  padding: 0;
  cursor: pointer;
  font: inherit;
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 1.4;
  letter-spacing: 0;
}

.bubble-hover-bar button[data-action="copy-message"],
.bubble-hover-bar button[data-action="favorite-message"],
.bubble-hover-bar button[data-action="quote-message"],
.bubble-hover-bar button[data-action="edit-message"] {
  font: inherit;
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 1.4;
  letter-spacing: 0;
}

.bubble-copy:hover {
  color: var(--text-subtle);
}

.subagent-output-actions {
  gap: 8px;
  padding-top: 3px;
  color: #adb5c1;
  font-size: calc(9px + var(--app-font-size-offset));
}

.subagent-output-actions .bubble-time,
.subagent-output-actions button[data-action="copy-message"],
.subagent-output-actions button[data-action="quote-message"] {
  font-size: inherit;
  line-height: 1.35;
}

.message-code-block {
