/* Keep the compact marker editor legible against dark graphite surfaces. */
.thread-marker-dialog {
  width: min(360px, calc(100vw - 44px));
  border: 1px solid var(--line);
}

.thread-marker-dialog form {
  gap: 16px;
  padding: 24px 26px 22px;
}

.thread-marker-dialog #threadMarkerNameInput {
  box-sizing: border-box;
  height: 42px;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: var(--surface-field);
  padding: 0 13px;
  caret-color: var(--brand-blue);
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease;
}

.thread-marker-dialog #threadMarkerNameInput:hover {
  border-color: var(--text-muted);
}

.thread-marker-dialog #threadMarkerNameInput:focus {
  border-color: var(--brand-blue);
  box-shadow: 0 0 0 3px rgba(22, 119, 255, 0.16);
}

.thread-marker-dialog footer {
  gap: 12px;
  padding-top: 2px;
}

.thread-marker-dialog .thread-dialog-primary,
.thread-marker-dialog .thread-dialog-secondary {
  width: 100%;
  height: 38px;
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease;
}

.thread-marker-dialog .thread-dialog-secondary {
  border: 1px solid var(--line);
}

.thread-marker-dialog button:focus-visible {
  outline: 2px solid var(--brand-blue);
  outline-offset: 2px;
}

