  border-radius: 12px;
  background: var(--surface-primary);
  box-shadow: 0 16px 38px rgba(17, 24, 39, 0.18);
  color: var(--text-primary);
  padding: 0;
}

.group-chat-picker {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  border-right: 1px solid #e4e5e8;
  background: #f4f4f6;
  padding-top: 22px;
}

.group-chat-search {
  display: grid;
  height: 34px;
  min-height: 34px;
  grid-template-columns: 16px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  margin: 0 24px 8px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: #fff;
  padding: 0 10px;
  color: #a3a7ae;
  transition: border-color 0.16s ease, background-color 0.16s ease, box-shadow 0.16s ease;
}

.group-chat-search:hover {
  border-color: #d7d9dd;
}

.group-chat-search:focus-within {
  border-color: rgba(17, 19, 21, 0.52);
  box-shadow: 0 0 0 2px rgba(17, 19, 21, 0.08);
}

.group-chat-search img {
  display: block;
  width: 16px;
  height: 16px;
  opacity: 0.58;
}

.group-chat-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
}

.group-chat-search input::placeholder {
  color: var(--text-placeholder);
}

.group-chat-options {
  min-height: 0;
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0 0 18px;
  scrollbar-color: var(--scrollbar-thumb-hidden) transparent;
  scrollbar-width: thin;
}

.group-chat-options::-webkit-scrollbar {
  width: var(--scrollbar-size);
}

.group-chat-selected-list::-webkit-scrollbar {
  width: 6px;
}

.group-chat-options::-webkit-scrollbar-thumb {
  border: var(--scrollbar-thumb-inset) solid transparent;
  border-radius: 999px;
  background-color: transparent;
  background-clip: content-box;
}

.group-chat-options::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}

.group-chat-picker:hover .group-chat-options {
  scrollbar-color: var(--scrollbar-thumb) transparent;
}

.group-chat-picker:hover .group-chat-options::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb);
}

.group-chat-options::-webkit-scrollbar-thumb:hover {
  background-color: var(--scrollbar-thumb-hover);
}

.group-chat-selected-list::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: #aeb1b6;
  background-clip: padding-box;
}

.group-chat-option-section {
  display: grid;
}

.group-chat-section-title {
  display: flex;
  width: 100%;
  min-height: 38px;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  padding: 0 24px;
  color: var(--text-primary);
  cursor: pointer;
  font-family: inherit;
  font-size: calc(14px + var(--app-font-size-offset));
  text-align: left;
  transition: background-color 0.14s ease;
}

.group-chat-section-title:hover {
  background: #ececef;
}

.group-chat-section-title:active {
  background: #e5e5e8;
}

.group-chat-section-title:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 2px rgba(17, 19, 21, 0.48);
}

.group-chat-section-title svg {
  width: 13px;
  height: 13px;
  color: #747981;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.6;
  transition: transform 0.16s ease;
}

.group-chat-option-section.collapsed .group-chat-section-title svg {
  transform: rotate(-90deg);
}

.group-chat-option-rows {
  display: grid;
}

.group-chat-option-rows[hidden] {
  display: none;
}

.group-chat-option {
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: 54px;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
  color: var(--text-primary);
  text-align: left;
  transition: background-color 0.14s ease;
}

.group-chat-option.has-quantity {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-right: 18px;
}

.group-chat-option:hover,
.group-chat-option:focus-within {
  background: #e9e9ec;
}

.group-chat-option:active {
  background: #e3e3e6;
}

.group-chat-option.selected,
.group-chat-option.selected:focus-within {
  background: transparent;
}

.group-chat-option.selected:hover {
  background: #e9e9ec;
}

.group-chat-option.existing,
.group-chat-option.existing:hover,
.group-chat-option.existing:active,
.group-chat-option.existing:focus-within,
.group-chat-option.unavailable,
.group-chat-option.unavailable:hover,
.group-chat-option.unavailable:active,
.group-chat-option.unavailable:focus-within {
  background: transparent;
}

.group-chat-option:focus-within {
  outline: 0;
  box-shadow: none;
}

.group-chat-option-select {
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: 54px;
  grid-template-columns: 18px 34px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  border: 0;
  background: transparent;
  padding: 6px 24px;
  color: inherit;
  font: inherit;
  text-align: left;
}

.group-chat-option.has-quantity .group-chat-option-select {
  padding-right: 12px;
}

.group-chat-option-select:focus-visible {
  outline: 0;
}

.group-chat-option-select:disabled {
  cursor: default;
  opacity: 0.62;
}

.group-chat-option.unavailable .group-chat-option-select {
  opacity: 0.48;
}

.group-chat-check {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border: 1.5px solid #9b9fa6;
  border-radius: 50%;
  background: transparent;
  color: #fff;
  transition: border-color 0.14s ease, background-color 0.14s ease;
}

.group-chat-option.selected .group-chat-check {
  border-color: #111315;
  background: #111315;
}

.group-chat-option.existing .group-chat-check {
  border-color: #a9adb4;
  background: #e2e3e6;
  color: #747981;
}

.group-chat-option.unavailable .group-chat-check {
  border-color: #c2c5ca;
  background: #f1f1f2;
  color: #a0a4aa;
}

.group-chat-check svg {
  width: 12px;
  height: 12px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.group-chat-option .contact-avatar.small,
.group-chat-selected-row .contact-avatar.small {
  width: 34px;
  height: 34px;
}

.group-chat-option-copy {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.group-chat-option-copy strong,
.group-chat-selected-row > strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 20px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.group-chat-option-copy small {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--text-subtle);
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 15px;
}

.group-chat-option-copy small i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #16c36a;
}

.group-chat-option-copy small i.standby,
.group-chat-option-copy small i.error {
  background: var(--contact-status-standby);
}

.group-chat-option-copy small i.loading {
  background: #8e96a3;
}

.group-chat-option-copy small.group-chat-existing-label {
  color: #8b9098;
}

.group-chat-quantity {
  position: relative;
  display: block;
  height: 24px;
  min-width: 52px;
  color: #5f6670;
}

.group-chat-quantity > summary {
  display: grid;
  width: 100%;
  height: 24px;
  grid-template-columns: auto 12px;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid #d4d7dc;
  border-radius: 8px;
  background: #f1f2f4;
  padding: 0 7px;
  color: #5f6670;
  cursor: pointer;
  list-style: none;
  transition:
    border-color 0.14s ease,
    background-color 0.14s ease,
    box-shadow 0.14s ease;
}

.group-chat-quantity > summary::-webkit-details-marker {
  display: none;
}

.group-chat-quantity > summary:hover {
  border-color: #bfc3c9;
  background: #e8e9eb;
}

.group-chat-quantity[open] > summary {
  border-color: #b3b7be;
  background: #e3e5e8;
  box-shadow: 0 0 0 2px rgba(63, 68, 75, 0.08);
}

.group-chat-quantity > summary:focus-visible {
  outline: 2px solid rgba(83, 88, 96, 0.55);
  outline-offset: 2px;
}

.group-chat-quantity > summary > strong {
  color: #4a4f57;
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 600;
  line-height: 16px;
}

.group-chat-quantity > summary svg {
  width: 10px;
  height: 10px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
  transition: transform 0.14s ease;
}

.group-chat-quantity[open] > summary svg {
  transform: rotate(180deg);
}

.group-chat-quantity-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 24;
  display: grid;
  width: 58px;
  gap: 1px;
  border: 1px solid #d0d3d8;
  border-radius: 10px;
  background: #f7f7f8;
  box-shadow: 0 8px 20px rgba(35, 39, 45, 0.16);
  padding: 4px;
}

.group-chat-quantity-menu button {
  width: 100%;
  height: 22px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #5f6670;
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
  white-space: nowrap;
  transition:
    background-color 0.12s ease,
    color 0.12s ease;
}

.group-chat-quantity-menu button:hover,
.group-chat-quantity-menu button:focus-visible {
  outline: 0;
  background: #e9eaec;
  color: #3f444b;
}

.group-chat-quantity-menu button:active {
  background: #dcdee1;
}

.group-chat-quantity-menu button[aria-checked="true"] {
  background: #e1e3e6;
  color: #353a40;
  font-weight: 600;
}

.group-chat-quantity-menu button:disabled {
  background: transparent;
  color: #a7abb2;
  cursor: default;
}

.group-chat-list-state {
  padding: 16px 24px;
  color: var(--text-subtle);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
}

.group-chat-selection {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  background: var(--surface-primary);
  padding: 26px 28px 28px;
}

.group-chat-selection > header {
  display: flex;
  min-height: 28px;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.group-chat-selection h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: calc(16px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 22px;
}

.group-chat-selection > header > span {
  color: #a3a6ad;
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 20px;
  white-space: nowrap;
}

.group-chat-selected-list {
  min-height: 0;
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 12px 0;
}

.group-chat-selected-row {
  display: grid;
  min-height: 54px;
  grid-template-columns: 34px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 11px;
}

.group-chat-selected-row.has-quantity {
  grid-template-columns: 34px minmax(0, 1fr) auto 18px;
}

.group-chat-selected-quantity {
  display: inline-flex;
  min-width: 54px;
  height: 26px;
  align-items: center;
  justify-content: center;
  border: 1px solid #d8dade;
  border-radius: 7px;
  background: #f5f5f6;
  padding: 0 7px;
  color: #5e6269;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 16px;
  white-space: nowrap;
}

.group-chat-selected-row > button {
  display: flex;
  width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 50%;
  background: #aeb1b5;
  color: #fff;
  padding: 0;
  line-height: 0;
  transition: background-color 0.14s ease, transform 0.14s ease;
}

.group-chat-selected-row > button svg {
  display: block;
  width: 10px;
  height: 10px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 2.4;
}

.group-chat-selected-row > button:hover {
  background: #91969c;
}

.group-chat-selected-row > button:active {
  transform: scale(0.92);
}

.group-chat-selected-row > button:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px rgba(17, 19, 21, 0.52);
}

.group-chat-selected-row > button:disabled {
  background: #d0d2d5;
  cursor: default;
}

.group-chat-empty-selection {
  display: grid;
  min-height: 100%;
  place-items: center;
  color: #b0b3b8;
  font-size: calc(13px + var(--app-font-size-offset));
  text-align: center;
}

.group-chat-selection > footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding-top: 8px;
}

.group-chat-selection > footer button {
  width: 120px;
  height: 36px;
  border: 0;
  border-radius: 999px;
  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 400;
  transition: background-color 0.14s ease, color 0.14s ease, transform 0.14s ease;
}

.group-chat-complete {
  background: #111315;
  color: #fff;
}

.group-chat-complete:hover {
  background: #292c30;
}

.group-chat-remove {
  background: #d64b55;
  color: #fff;
}

.group-chat-remove:hover {
  background: #bf3f49;
}

.group-chat-complete:active,
.group-chat-remove:active,
.group-chat-cancel:active {
  transform: translateY(1px);
}

.group-chat-cancel {
  background: #f0f0f1;
  color: #26272a;
}

.group-chat-cancel:hover {
  background: #e5e5e7;
}

.group-chat-selection > footer button:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px rgba(17, 19, 21, 0.52);
}

.group-chat-selection > footer button:disabled {
  background: #dedfe1;
  color: #a4a7ac;
  cursor: default;
  transform: none;
}

