html[data-theme="dark"] .group-chat-dialog[open] .group-chat-complete:hover:not(:disabled) {
  border-color: #6e747e;
  background: #17191c;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-remove:not(:disabled) {
  border: 1px solid #d96b74;
  background: #a93843;
  color: #fff;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-remove:hover:not(:disabled) {
  border-color: #ec7c85;
  background: #bd4651;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-cancel:not(:disabled) {
  border: 1px solid #3b3e45;
  background: #292c31;
  color: #f1f2f4;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-cancel:hover:not(:disabled) {
  border-color: #4a4e56;
  background: #34373d;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-selection > footer button:disabled {
  border-color: #33363d;
  background: #25282d;
  color: #7f8792;
}

html[data-theme="dark"] .group-chat-dialog[open] .group-chat-selection > footer button:focus-visible,
html[data-theme="dark"] .group-chat-selected-row > button:focus-visible {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.44);
}

@media (max-width: 760px), (max-height: 700px) {
  .group-chat-dialog[open] {
    width: calc(100vw - 32px);
    height: calc(100vh - 32px);
    grid-template-columns: minmax(260px, 44%) minmax(0, 1fr);
  }

  .group-chat-search {
    margin-right: 20px;
    margin-left: 20px;
  }

  .group-chat-section-title {
    padding-right: 20px;
    padding-left: 20px;
  }

  .group-chat-option.has-quantity {
    padding-right: 16px;
  }

  .group-chat-option-select {
    padding-right: 20px;
    padding-left: 20px;
  }

  .group-chat-option.has-quantity .group-chat-option-select {
    padding-right: 10px;
  }

  .group-chat-selection {
    padding-right: 24px;
    padding-left: 24px;
  }

  .group-chat-selection > footer {
    gap: 16px;
  }

  .group-chat-selection > footer button {
    width: min(150px, 44%);
  }
}

/* Local group chat conversation and member information panel. */
.local-group-chat-message-area {
  min-height: 0;
}

.local-group-chat-scroller {
  display: block;
  padding: 34px 42px;
}

.local-group-chat-join-notice {
  display: flex;
  width: fit-content;
  max-width: min(100%, 760px);
  min-height: 32px;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 5px 2px;
  margin: 0 auto;
  border-radius: 10px;
  color: var(--text-tertiary);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 22px;
}

.local-group-chat-join-member {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  color: var(--text-subtle);
  white-space: nowrap;
}

.local-group-chat-join-avatar {
  display: grid;
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  overflow: hidden;
  place-items: center;
  border-radius: 5px;
  background: var(--surface-soft);
  color: var(--text-secondary);
  font-size: calc(8px + var(--app-font-size-offset));
  font-weight: 700;
}

.local-group-chat-join-avatar img,
.local-group-chat-member-avatar img,
.local-group-chat-member-profile-avatar img,
.local-group-chat-avatar-content img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.local-group-chat-join-separator {
  color: var(--text-muted);
}

.local-group-chat-join-copy {
  margin-left: 3px;
  color: var(--text-muted);
  white-space: nowrap;
}

.local-group-chat-member-event {
  display: flex;
  width: fit-content;
  max-width: min(100%, 760px);
  min-height: 32px;
  align-items: center;
  justify-content: center;
  margin: 18px auto 0;
  color: var(--text-tertiary);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 22px;
}

.local-group-chat-member-event-content {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.local-group-chat-member-event-copy {
  color: var(--text-muted);
  white-space: nowrap;
}

.local-group-chat-member-event-name {
  color: var(--text-subtle);
}

.local-group-chat-avatar-content {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  background: var(--surface-primary);
}

.local-group-chat-avatar-content.tone-orange,
.local-group-chat-join-avatar.tone-orange,
.local-group-chat-member-avatar.tone-orange,
.local-group-chat-member-profile-avatar.tone-orange {
  background: #ee7b56;
  color: #fff;
}

.local-group-chat-avatar-content.tone-blue,
.local-group-chat-join-avatar.tone-blue,
.local-group-chat-member-avatar.tone-blue,
.local-group-chat-member-profile-avatar.tone-blue {
  background: #3b82f6;
  color: #fff;
}

.local-group-chat-avatar-content.tone-black,
.local-group-chat-join-avatar.tone-black,
.local-group-chat-member-avatar.tone-black,
.local-group-chat-member-profile-avatar.tone-black {
  background: #111315;
  color: #fff;
}

.local-group-chat-avatar-content.tone-violet,
.local-group-chat-join-avatar.tone-violet,
.local-group-chat-member-avatar.tone-violet,
.local-group-chat-member-profile-avatar.tone-violet {
  background: #7357d8;
  color: #fff;
}

.local-group-chat-avatar-content.tone-green,
.local-group-chat-join-avatar.tone-green,
.local-group-chat-member-avatar.tone-green,
.local-group-chat-member-profile-avatar.tone-green {
  background: #27a870;
  color: #fff;
}

.local-group-chat-avatar-content.tone-person,
.local-group-chat-join-avatar.tone-person,
.local-group-chat-member-avatar.tone-person,
.local-group-chat-member-profile-avatar.tone-person {
  background: #e7ebf0;
  color: #4b5563;
}

.local-group-chat-members-panel {
  width: 270px;
  max-width: 270px;
  background: #fbfbfc;
}

.local-group-chat-members-inner {
  width: 270px;
  min-width: 270px;
  background: #fbfbfc;
}

.local-group-chat-members-scroll {
  min-height: 0;
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 14px clamp(12px, 5%, 14px) 24px;
}

.local-group-chat-member-search {
  display: grid;
  width: 100%;
  height: 32px;
  box-sizing: border-box;
  grid-template-columns: 14px minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  border: 1px solid #d9dde4;
  border-radius: 7px;
  background: #fff;
  padding: 0 9px;
  color: var(--text-muted);
  transition:
    border-color 0.16s ease,
    background-color 0.16s ease,
    box-shadow 0.16s ease;
}

.local-group-chat-member-search:hover {
  border-color: #c5cad2;
  background: #fdfdfd;
}

.local-group-chat-member-search:focus-within {
  border-color: rgba(17, 24, 39, 0.5);
  background: #fff;
  box-shadow: 0 0 0 2px rgba(17, 24, 39, 0.08);
}

.local-group-chat-member-search img {
  display: block;
  width: 14px;
  height: 14px;
  opacity: 0.58;
}

.local-group-chat-member-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: calc(11px + var(--app-font-size-offset));
}

.local-group-chat-member-search input::placeholder {
  color: var(--text-placeholder);
}

.local-group-chat-member-search input:disabled {
  color: var(--text-muted);
  cursor: default;
}

.local-group-chat-member-search:has(input:disabled) {
  border-color: var(--border-subtle);
  background: var(--surface-disabled);
  opacity: 0.66;
}

.local-group-chat-members-section {
  padding: 16px 0 15px;
}

.local-group-chat-member-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px clamp(5px, 2%, 6px);
}

.local-group-chat-member-cell {
  display: grid;
  width: 100%;
  min-width: 0;
  justify-items: center;
  gap: 5px;
  border: 1px solid transparent;
  border-radius: 7px;
  outline: 0;
  background: transparent;
  padding: 3px 1px;
  color: var(--text-secondary);
  cursor: pointer;
  transition:
    border-color 0.16s ease,
    background-color 0.16s ease,
    color 0.16s ease,
    transform 0.1s ease;
}

.local-group-chat-member-cell:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.local-group-chat-member-cell:active {
  background: var(--surface-active-translucent);
  transform: scale(0.97);
}

.local-group-chat-member-cell:focus-visible {
  border-color: var(--brand-blue);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.local-group-chat-member-cell:disabled {
  background: transparent;
  color: var(--text-placeholder);
  cursor: default;
  opacity: 0.5;
  transform: none;
}

.local-group-chat-member-cell.muted .local-group-chat-member-avatar {
  filter: grayscale(0.7);
  opacity: 0.58;
}

.local-group-chat-member-avatar {
  display: grid;
  width: 35px;
  height: 35px;
  overflow: hidden;
  place-items: center;
  border-radius: 9px;
  background: var(--surface-soft);
  color: var(--text-secondary);
  box-shadow: 0 1px 5px rgba(17, 24, 39, 0.08);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 700;
}

.local-group-chat-add-member-icon {
  display: grid;
  width: 35px;
  height: 35px;
  box-sizing: border-box;
  place-items: center;
  border: 1px dashed #aeb4bd;
  border-radius: 9px;
  background: transparent;
  color: #79818c;
  transition:
    border-color 0.16s ease,
    background-color 0.16s ease,
    color 0.16s ease;
}

.local-group-chat-add-member-icon svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 1.5;
}

.local-group-chat-add-member:hover .local-group-chat-add-member-icon,
.local-group-chat-remove-member:hover .local-group-chat-add-member-icon {
  border-color: #747d89;
  background: #fff;
  color: #3f4650;
}

.local-group-chat-add-member:active .local-group-chat-add-member-icon,
.local-group-chat-remove-member:active .local-group-chat-add-member-icon {
  border-color: #626b76;
  background: #f3f4f6;
  color: #2f353d;
}

.local-group-chat-add-member:focus-visible .local-group-chat-add-member-icon,
.local-group-chat-remove-member:focus-visible .local-group-chat-add-member-icon {
  border-color: var(--brand-blue);
  background: var(--surface-primary);
  color: var(--brand-blue);
}

.local-group-chat-add-member:disabled .local-group-chat-add-member-icon,
.local-group-chat-remove-member:disabled .local-group-chat-add-member-icon {
  border-color: var(--border-subtle);
  background: transparent;
  color: var(--text-placeholder);
}

.local-group-chat-member-name {
  width: 100%;
  overflow: hidden;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 15px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.local-group-chat-member-empty {
  display: grid;
  min-height: 80px;
  place-items: center;
  color: var(--text-muted);
  font-size: calc(11px + var(--app-font-size-offset));
}

.local-group-chat-info {
  display: grid;
  gap: 18px;
  border-top: 1px solid #eceef1;
  padding: 18px 2px 0;
}

.local-group-chat-info-item {
  display: grid;
  gap: 4px;
}

.local-group-chat-info-item h3,
.local-group-chat-info-item p,
.local-group-chat-info-value {
  margin: 0;
}

.local-group-chat-info-item h3 {
  color: var(--text-primary);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 17px;
}

.local-group-chat-info-item p {
  color: var(--text-muted);
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  overflow-wrap: anywhere;
}

.local-group-chat-info-value {
  display: inline-block;
  max-width: 100%;
  justify-self: start;
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: 5px;
  outline: 0;
  background: transparent;
  padding: 1px 4px;
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  overflow-wrap: anywhere;
  text-align: left;
  white-space: normal;
  transition:
    border-color 0.14s ease,
    background-color 0.14s ease,
    color 0.14s ease;
}

.local-group-chat-info-value.empty {
  color: var(--text-placeholder);
}

.local-group-chat-info-value:hover {
  background: rgba(17, 24, 39, 0.045);
  color: var(--text-secondary);
}

.local-group-chat-info-value:active {
  background: rgba(17, 24, 39, 0.085);
  color: var(--text-primary);
}

.local-group-chat-info-value:focus-visible {
  border-color: rgba(59, 130, 246, 0.72);
  background: rgba(59, 130, 246, 0.06);
  color: var(--text-primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.14);
}

.local-group-chat-info-value:disabled {
  background: transparent;
  color: var(--text-placeholder);
  cursor: default;
  opacity: 0.58;
}

.local-group-chat-info-edit-icon {
  display: inline-grid;
  width: 16px;
  height: 16px;
  margin-left: 3px;
  place-items: center;
  color: #8a929e;
  opacity: 0;
  transform: translateX(-2px);
  transition:
    color 0.14s ease,
    opacity 0.14s ease,
    transform 0.14s ease;
  vertical-align: -3px;
}

.local-group-chat-info-edit-icon svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.65;
}

.local-group-chat-info-value:hover .local-group-chat-info-edit-icon,
.local-group-chat-info-value:active .local-group-chat-info-edit-icon,
.local-group-chat-info-value:focus-visible .local-group-chat-info-edit-icon {
  opacity: 1;
  transform: translateX(0);
}

.local-group-chat-info-value:hover .local-group-chat-info-edit-icon {
  color: #626b77;
}

.local-group-chat-info-editor {
  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 6px;
}

.local-group-chat-info-editor input,
.local-group-chat-info-editor textarea {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border: 1px solid #cfd4dc;
  border-radius: 6px;
  outline: 0;
  background: #fff;
  padding: 6px 8px;
  color: #252a32;
  caret-color: #2563eb;
  font: inherit;
  font-size: calc(11px + var(--app-font-size-offset));
  line-height: 18px;
  transition:
    border-color 0.14s ease,
    background-color 0.14s ease,
    box-shadow 0.14s ease;
}

.local-group-chat-info-editor input {
  height: 32px;
}

.local-group-chat-info-editor textarea {
  min-height: 62px;
  resize: vertical;
}

.local-group-chat-info-editor input:hover,
.local-group-chat-info-editor textarea:hover {
  border-color: #aeb5bf;
  background: #fdfdfd;
}

.local-group-chat-info-editor input:focus,
.local-group-chat-info-editor textarea:focus {
  border-color: #3b82f6;
  background: #fff;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.14);
}

.local-group-chat-info-editor input:disabled,
.local-group-chat-info-editor textarea:disabled {
  border-color: #e0e3e8;
  background: #f1f3f5;
  color: #9299a3;
  cursor: default;
}

.local-group-chat-info-editor.has-error input,
.local-group-chat-info-editor.has-error textarea {
  border-color: #dc4c42;
}

.local-group-chat-info-editor-actions {
  display: flex;
  gap: 4px;
}

.local-group-chat-info-editor-actions button {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  border: 1px solid #d8dce3;
  border-radius: 6px;
  outline: 0;
  background: #f7f8fa;
  padding: 0;
  color: #747c87;
  cursor: pointer;
  transition:
    border-color 0.14s ease,
    background-color 0.14s ease,
    color 0.14s ease,
    transform 0.1s ease;
}

.local-group-chat-info-editor-actions button.save {
  border-color: #b9d0f7;
  background: #eef5ff;
  color: #2563c9;
}

.local-group-chat-info-editor-actions button:hover {
  border-color: #aeb5bf;
  background: #eef0f3;
  color: #3d444e;
}

.local-group-chat-info-editor-actions button.save:hover {
  border-color: #8fb5ef;
  background: #dfeeff;
  color: #174fa9;
}

.local-group-chat-info-editor-actions button:active {
  background: #e1e4e8;
  transform: scale(0.94);
}

.local-group-chat-info-editor-actions button.save:active {
  background: #cfe3ff;
}

.local-group-chat-info-editor-actions button:focus-visible {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.18);
}

.local-group-chat-info-editor-actions button:disabled {
  border-color: #e2e5e9;
  background: #f2f3f5;
  color: #afb5bd;
  cursor: default;
  transform: none;
}

.local-group-chat-info-editor-actions svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.9;
}

.local-group-chat-info-editor-error {
  grid-column: 1 / -1;
  color: #c9362c;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 15px;
}

