/* Trading Expert keeps the market canvas on the left and the normal conversation
   stream on the right. The conversation panel owns its composer so it remains
   available when the market canvas is collapsed. */
.desktop-body.trading-expert-layout {
  --trading-expert-left-panel-min-width: 192px;
  --trading-expert-panel-min-width: 300px;
  --trading-expert-panel-width: var(--trading-expert-panel-min-width);
  --trading-expert-panel-divider: #e3e8ef;
  --trading-expert-resize-grip: #737d8c;
  --trading-expert-resize-grip-active: #2f80ed;
  --trading-expert-resize-hover: rgba(47, 128, 237, 0.08);
  background: var(--app-chrome-background);
}

.chat-list.trading-expert-task-list {
  --trading-expert-panel-divider: #e3e8ef;
  border-right: 0;
}

.desktop-body.trading-expert-layout > .trading-expert-chat-panel {
  position: relative;
  z-index: 3;
  min-width: 0;
  flex: 1 1 auto;
  overflow: visible;
  border-radius: 16px 0 0 0;
  background: #ffffff;
  box-shadow: none;
}

.desktop-body.trading-expert-layout
  > .trading-expert-chat-panel
  > .trading-expert-market {
  border-right: 0;
  border-top-left-radius: inherit;
}

.desktop-body.trading-expert-layout > .trading-expert-collapse-controls {
