}

.desktop-body.trading-expert-layout
  > .trading-expert-panel
  > .composer
  .trading-expert-mention-popover
  button:focus-visible {
  outline: 2px solid var(--brand-blue);
  outline-offset: -2px;
  background: var(--selection-soft);
}

.desktop-body.trading-expert-layout
