  button:active {
  background: var(--selection-soft);
}

.desktop-body.trading-expert-layout
  > .trading-expert-panel
  > .composer
  .composer-mention-root-item
  > svg {
  transform: rotate(180deg);
}

.desktop-body.trading-expert-layout
  > .trading-expert-panel
  > .composer
  .composer-mode-picker {
  display: none;
}

/* The standard model menu is positioned from its compact footer trigger. In
   the 300px Trading Expert panel that puts the 224px menu past the clipped
   panel edge. While the chart is visible, let the picker span the composer,
   keep the trigger in its original footer position, and center the menu on
   the full composer instead. When the chart is collapsed, the base picker
   rules keep the menu anchored above its trigger in the expanded composer. */
.desktop-body.trading-expert-layout:not(.trading-expert-chart-collapsed)
  > .trading-expert-panel
  > .composer
  > .composer-model-picker {
  right: 0;
  left: 0;
  width: auto;
  margin: 0;
  pointer-events: none;
}

.desktop-body.trading-expert-layout:not(.trading-expert-chart-collapsed)
  > .trading-expert-panel
  > .composer
  > .composer-model-picker
  > .chat-title-group-wrap {
  position: absolute;
  right: 104px;
  bottom: 0;
  pointer-events: auto;
}

.desktop-body.trading-expert-layout:not(.trading-expert-chart-collapsed)
  > .trading-expert-panel
  > .composer
  > .composer-model-picker
  > .composer-model-menu {
  right: auto;
  left: 50%;
  width: min(224px, calc(100% - 24px));
  pointer-events: auto;
  transform: translateX(-50%);
}

/* Media reference rails and quotes change the composer height. Let the message
   area share the available space instead of hiding messages behind the form. */
.desktop-body.trading-expert-layout
  > .trading-expert-panel:has(> .composer.media-creation-composer) {
  flex-direction: column;
}

.desktop-body.trading-expert-layout
  > .trading-expert-panel:has(> .composer.media-creation-composer)
  > .agent-panel-inner {
  height: auto;
  min-height: 0;
  flex: 1 1 0;
}

.desktop-body.trading-expert-layout
  > .trading-expert-panel
  > .composer.media-creation-composer {
  position: relative;
  inset: auto;
  flex: 0 0 auto;
  margin: 0 12px 13px;
}

.desktop-body.trading-expert-layout
  > .trading-expert-panel:has(> .composer.media-creation-composer)
  .trading-expert-dashboard.chat {
  padding-bottom: 0;
}

/* Keep media parameters separate from the model/microphone/send row when the
   user restores the chart while a media model is still selected. */
.desktop-body.trading-expert-layout:not(.trading-expert-chart-collapsed)
  > .trading-expert-panel
  > .composer.media-creation-composer
  .composer-tools {
  bottom: 44px;
}

.desktop-body.trading-expert-layout:not(.trading-expert-chart-collapsed)
  > .trading-expert-panel
  > .composer.media-creation-composer
  .composer-input-wrap {
  margin-bottom: 74px;
}

