.trading-expert-workspace-placeholder {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1 1 auto;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-right: 1px solid var(--line);
  background: var(--surface-primary);
  color: var(--text-secondary);
}

.trading-expert-workspace-placeholder-content {
  display: flex;
  max-width: min(420px, 80%);
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.trading-expert-workspace-placeholder-icon {
  display: inline-flex;
  width: 38px;
  height: 38px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-control);
  border-radius: 12px;
  background: var(--surface-subtle);
  color: var(--text-tertiary);
  font-size: calc(24px + var(--app-font-size-offset));
  line-height: 1;
}

.trading-expert-workspace-placeholder-content strong {
  color: var(--text-primary);
  font-size: calc(16px + var(--app-font-size-offset));
  font-weight: 600;
}

.trading-expert-workspace-placeholder-content > span:last-child {
  color: var(--text-tertiary);
  font-size: calc(13px + var(--app-font-size-offset));
}

.trading-market-overview {
  position: relative;
  z-index: 30;
  display: flex;
  height: 36.4px;
  min-width: 0;
  flex: 0 0 36.4px;
  align-items: center;
  gap: 12px;
  overflow: visible;
  border-bottom: 0;
  background: var(--trading-market-panel);
  box-shadow: none;
  padding: 0 10px 0 0;
}

.trading-market-symbol-wrap {
  position: relative;
  flex: 0 0 auto;
}

.trading-market-chart-actions {
  position: relative;
  z-index: 86;
  display: flex;
  width: 62px;
  height: 32px;
  flex: 0 0 62px;
  align-items: center;
  justify-content: center;
  gap: 2px;
  margin-left: -8px;
}

.trading-market-chart-action {
  display: grid;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--trading-market-muted);
  cursor: pointer;
  font: inherit;
  transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease, transform 0.1s ease;
}

.trading-market-chart-action:hover:not(:disabled),
.trading-market-chart-action.active,
.trading-market-chart-action[aria-expanded="true"] {
  border-color: var(--trading-market-border);
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-market-chart-action:active:not(:disabled) {
  background: var(--trading-market-control-hover);
  transform: translateY(1px);
}

.trading-market-chart-action:focus-visible,
.trading-market-layout-picker button:focus-visible {
  outline: 2px solid var(--trading-market-accent);
  outline-offset: 1px;
}

.trading-market-layout-picker[hidden],
.trading-chart-settings-backdrop[hidden] {
  display: none !important;
}

.trading-market-chart-action:disabled,
.trading-market-layout-row button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.trading-market-chart-action svg {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.trading-market-chart-settings-tooltip {
  position: absolute;
  z-index: 95;
  top: calc(100% + 7px);
  left: 0;
  display: grid;
  box-sizing: border-box;
  width: 300px;
  max-width: calc(100vw - 28px);
  gap: 4px;
  visibility: hidden;
  border: 1px solid var(--trading-market-border);
  border-radius: 8px;
  background: var(--trading-market-panel);
  box-shadow: 0 12px 32px color-mix(in srgb, var(--trading-market-text) 14%, transparent);
  padding: 13px 15px 14px;
  color: var(--trading-market-text);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-3px);
  transition: opacity 0.14s ease, transform 0.14s ease, visibility 0s linear 0.14s;
}

.trading-market-chart-settings-tooltip strong {
  font-size: calc(14px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 22px;
}

.trading-market-chart-settings-tooltip span {
  color: var(--trading-market-muted);
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 20px;
}

.trading-market-chart-action[data-market-action="open-chart-settings"]:hover:not(:disabled, [aria-expanded="true"])
  + .trading-market-chart-settings-tooltip,
.trading-market-chart-action[data-market-action="open-chart-settings"]:focus-visible:not(:disabled, [aria-expanded="true"])
  + .trading-market-chart-settings-tooltip {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
  transition-delay: 0.32s, 0.32s, 0s;
}

.trading-market-chart-action[data-market-action="open-chart-settings"]:focus-visible:not(:disabled, [aria-expanded="true"])
  + .trading-market-chart-settings-tooltip {
  transition-delay: 0s;
}

@media (prefers-reduced-motion: reduce) {
  .trading-market-chart-settings-tooltip {
    transform: none;
    transition: none;
  }
}

.trading-market-layout-picker {
  position: absolute;
  z-index: 94;
  top: calc(100% + 5px);
  left: 0;
  width: min(390px, calc(100vw - 100px));
  max-height: min(650px, calc(100vh - 92px));
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--trading-market-border);
  border-radius: 8px;
  background: var(--trading-market-panel);
  box-shadow: 0 20px 56px rgba(17, 24, 39, 0.2);
  color: var(--trading-market-text);
  overscroll-behavior: contain;
}

.trading-market-layout-picker.floating {
  z-index: 140;
  margin: 0;
}

.trading-market-layout-picker > header {
  display: grid;
  gap: 2px;
  border-bottom: 1px solid var(--trading-market-border);
  padding: 12px 14px 10px;
}

.trading-market-layout-picker > header strong {
  font-size: calc(13px + var(--app-font-size-offset));
}

.trading-market-layout-picker > header span {
  color: var(--trading-market-muted);
  font-size: calc(10px + var(--app-font-size-offset));
}

.trading-market-layout-rows {
  display: grid;
  padding: 5px 0 8px;
}

.trading-market-layout-row {
  display: grid;
  min-height: 50px;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  border-bottom: 1px solid color-mix(in srgb, var(--trading-market-border) 70%, transparent);
  padding: 4px 10px 4px 4px;
}

.trading-market-layout-row:last-child {
  border-bottom: 0;
}

.trading-market-layout-row > span {
  color: var(--trading-market-muted);
  font-size: calc(11px + var(--app-font-size-offset));
  text-align: center;
}

.trading-market-layout-row > div {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.trading-market-layout-row button {
  display: grid;
  width: 43px;
  height: 36px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--trading-market-muted);
  cursor: pointer;
  padding: 5px 7px;
}

.trading-market-layout-row button:hover {
  border-color: var(--trading-market-border);
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-market-layout-row button.selected {
  border-color: color-mix(in srgb, var(--trading-market-accent) 64%, var(--trading-market-border));
  background: var(--trading-market-accent-soft);
  color: var(--trading-market-accent);
}

.trading-market-layout-row button:active {
  background: var(--trading-market-control-hover);
}

.trading-market-layout-row button > .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.trading-market-layout-icon {
  position: relative;
  display: block;
  width: 28px;
  height: 22px;
}

.trading-market-layout-icon i {
  position: absolute;
  display: block;
  border: 1.2px solid currentColor;
  background: color-mix(in srgb, currentColor 8%, transparent);
  box-shadow: inset 0 0 0 1px var(--trading-market-panel);
}

/* The titlebar owns the full middle slot. Favorites keep a 100px basis while
   the rail has room, then shrink together so all visible cards stay in view. */
.trading-market-favorite-tickers {
  display: flex;
  min-width: 0;
  height: 36px;
  flex: 1 1 auto;
  align-items: stretch;
  gap: 4px;
  overflow-x: hidden;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  touch-action: pan-x;
}

.trading-market-favorite-tickers.sorting {
  cursor: grabbing;
  scroll-behavior: auto;
  user-select: none;
}

.trading-market-favorite-tickers::-webkit-scrollbar {
  display: none;
}

.trading-market-favorite-tickers[hidden] {
  display: none !important;
}

.trading-market-favorite-ticker {
  position: relative;
  display: grid;
  width: 100px;
