.trading-order-position-card.short .trading-order-position-card-side {
  background: color-mix(in srgb, var(--trading-order-position-short) 14%, transparent);
  color: var(--trading-order-position-short);
}

.trading-order-position-card-featured {
  display: grid;
  margin-top: 6px;
  grid-template-columns: 2fr 1fr;
  gap: 8px;
}

.trading-order-position-card-featured > div,
.trading-order-position-card-metrics > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.trading-order-position-card-featured span,
.trading-order-position-card-metrics span {
  overflow: hidden;
  color: var(--trading-order-card-muted);
  font-size: calc(10px + var(--app-font-size-offset));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trading-order-position-card-featured strong {
  color: var(--trading-order-card-text);
  font-size: calc(16px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  line-height: 1.15;
}

.trading-order-position-card-featured .positive strong {
  color: var(--trading-order-pnl-profit);
}

.trading-order-position-card-featured .negative strong {
  color: var(--trading-order-pnl-loss);
}

.trading-order-position-card-featured > div:last-child {
  transform: translateX(7px);
}

.trading-order-position-card-featured > div:last-child > span {
  margin-left: 4px;
}

.trading-order-position-card-metrics {
  display: grid;
  margin-top: 6px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
}

.trading-order-position-card-metrics strong {
  overflow: hidden;
  color: var(--trading-order-card-text);
  font-size: calc(13px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trading-order-position-card-metrics > div:nth-child(3n) strong {
  margin-left: 10px;
}

.trading-order-position-card-metrics > div:nth-child(3n) > span {
  margin-left: 10px;
}

.trading-order-commission-card-intro {
  display: flex;
  align-items: baseline;
  gap: 14px;
  margin-top: 8px;
  white-space: nowrap;
}

.trading-order-commission-card-intro > strong {
  color: var(--trading-order-pnl-profit);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 500;
}

.trading-order-commission-card.short .trading-order-commission-card-intro > strong {
  color: var(--trading-order-pnl-loss);
}

.trading-order-commission-card-intro time {
  color: var(--trading-order-card-muted);
  font-size: calc(10px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
}

.trading-order-commission-card-details {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.trading-order-commission-card-details > div {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: space-between;
  gap: 28px;
}

.trading-order-commission-card-details span {
  color: var(--trading-order-card-muted);
  font-size: calc(11px + var(--app-font-size-offset));
  white-space: nowrap;
}

.trading-order-commission-card-details strong {
  min-width: 0;
  color: var(--trading-order-card-text);
  font-size: calc(13px + var(--app-font-size-offset));
  font-variant-numeric: tabular-nums;
  font-weight: 400;
  overflow-wrap: anywhere;
  text-align: right;
}

.trading-ai-cursor {
  color: var(--trading-ai-cursor);
  filter: drop-shadow(0 2px 5px color-mix(in srgb, var(--trading-ai-cursor) 34%, transparent));
  pointer-events: none;
}

.trading-ai-cursor-pointer {
  fill: var(--trading-ai-cursor-contrast);
  stroke: currentColor;
  stroke-linejoin: round;
  stroke-width: 1.8;
  vector-effect: non-scaling-stroke;
}

.trading-ai-cursor-ripple {
  fill: color-mix(in srgb, var(--trading-ai-cursor) 18%, transparent);
  stroke: currentColor;
  stroke-width: 1.4;
  opacity: 0;
  vector-effect: non-scaling-stroke;
}

.trading-ai-cursor.pulse .trading-ai-cursor-ripple {
  animation: trading-ai-cursor-pulse 0.42s ease-out;
}

.trading-ai-cursor-badge rect {
  fill: var(--trading-ai-cursor);
  stroke: var(--trading-market-panel);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.trading-ai-cursor-badge text {
  fill: var(--trading-ai-cursor-contrast);
  font-size: calc(8px + var(--app-font-size-offset));
  font-weight: 750;
  letter-spacing: 0.04em;
}

.trading-ai-inline-label {
  paint-order: stroke fill;
  stroke: var(--trading-market-panel);
  stroke-width: 3px;
  stroke-linejoin: round;
  text-anchor: middle;
}

.trading-ai-inline-label.trading-price-action-candlestick-label {
  fill: var(--trading-price-action-candlestick-label);
  paint-order: normal;
  stroke: none;
  font-weight: 400;
}

.trading-price-action-candlestick-label-leader {
  fill: none;
  stroke: var(--trading-price-action-candlestick-label);
  stroke-width: 1.2px;
  stroke-dasharray: 4 4;
  stroke-linecap: round;
  opacity: 0.78;
  vector-effect: non-scaling-stroke;
}

.trading-price-action-candlestick-label-target {
  fill: var(--trading-price-action-candlestick-label);
  stroke: none;
  opacity: 0.9;
}

.trading-price-action-candlestick-pattern-ellipse {
  fill: var(--trading-price-action-candlestick-label);
  fill-opacity: 0.035;
  stroke: var(--trading-price-action-candlestick-label);
  stroke-width: 0.8px;
  stroke-dasharray: none;
  opacity: 0.96;
  vector-effect: non-scaling-stroke;
}

@keyframes trading-ai-cursor-pulse {
  0% { opacity: 0.72; transform: scale(0.55); }
  100% { opacity: 0; transform: scale(2.4); }
}

.trading-fibonacci-label {
  paint-order: stroke fill;
  stroke: var(--trading-fibonacci-label-outline);
  stroke-width: 3px;
  stroke-linejoin: round;
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 600;
  letter-spacing: 0.01em;
}

.trading-fibonacci-level-line,
.trading-fibonacci-connector {
  pointer-events: none;
}

.trading-drawing-hit-target {
  fill: none;
  stroke: transparent;
  stroke-width: 14px;
  cursor: move;
  pointer-events: stroke;
  touch-action: none;
  vector-effect: non-scaling-stroke;
}

.trading-drawing-hit-target.point {
  fill: transparent;
  stroke: none;
  cursor: move;
  pointer-events: all;
}

.trading-drawing-hit-target.area {
  fill: transparent;
  stroke: none;
  cursor: move;
  pointer-events: all;
}

.trading-drawing-handle {
  cursor: grab;
  filter: drop-shadow(0 1px 2px color-mix(in srgb, var(--trading-market-text) 18%, transparent));
  pointer-events: all;
  touch-action: none;
}

.trading-drawing-handle.fibonacci {
  filter: drop-shadow(0 1px 2px color-mix(in srgb, var(--trading-fibonacci-handle-stroke) 28%, transparent));
}

.trading-drawing-layer.drawing-active .trading-drawing-hit-target,
.trading-drawing-layer.drawing-active .trading-drawing-handle {
  pointer-events: none;
}

[data-drawing-id][data-locked="true"] .trading-drawing-hit-target,
[data-drawing-id][data-locked="true"] .trading-drawing-handle {
  cursor: not-allowed;
}

.trading-drawing-axis-markers {
  position: absolute;
  inset: 0;
  z-index: 9;
  overflow: hidden;
  pointer-events: none;
}

.trading-drawing-axis-marker {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 1px;
  background: var(--trading-drawing-axis-marker);
  color: var(--trading-drawing-axis-marker-text);
  font-family: "Segoe UI", "Microsoft YaHei", Arial, sans-serif;
  font-feature-settings: "zero" 0;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  text-align: center;
  white-space: nowrap;
}

.trading-drawing-axis-marker.price {
  height: 24px;
  padding: 0 5px;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 24px;
  transform: translateY(-50%);
}

.trading-drawing-axis-marker.time {
  bottom: 4px;
  min-width: 132px;
  height: 22px;
  padding: 2px 9px;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 18px;
  transform: translateX(-50%);
}

.trading-drawing-selection {
  position: absolute;
  z-index: 12;
  display: flex;
  height: 42px;
  align-items: stretch;
  border: 1px solid var(--trading-market-border);
  border-radius: 6px;
  background: var(--trading-market-panel);
  box-shadow: 0 10px 28px rgba(25, 43, 68, 0.18);
  color: var(--trading-market-muted);
  user-select: none;
  -webkit-user-select: none;
}

.trading-ai-text-size-toolbar {
  position: absolute;
  z-index: 13;
  box-sizing: border-box;
  display: flex;
  height: 34px;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--trading-market-border);
  border-radius: 7px;
  background: color-mix(in srgb, var(--trading-market-panel) 96%, transparent);
  box-shadow: 0 8px 22px rgba(25, 43, 68, 0.2);
  color: var(--trading-market-muted);
  pointer-events: auto;
  user-select: none;
  -webkit-user-select: none;
}

.trading-ai-text-size-toolbar[hidden] {
  display: none !important;
}

.trading-ai-text-size-toolbar > button {
  display: grid;
  width: 30px;
  min-width: 30px;
  height: 28px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--trading-market-muted);
  font: inherit;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease, opacity 0.14s ease;
}

.trading-ai-text-size-toolbar > button > span {
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 700;
  line-height: 1;
}

.trading-ai-text-size-toolbar > button:hover,
.trading-ai-text-size-toolbar > button:focus-visible {
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-ai-text-size-toolbar > button:focus-visible {
  outline: 2px solid var(--trading-market-accent);
  outline-offset: 0;
}

.trading-ai-text-size-toolbar > button:active {
  background: var(--trading-market-accent-soft);
  color: var(--trading-market-accent);
}

.trading-ai-text-size-toolbar > button:disabled {
  background: transparent;
  color: var(--trading-market-muted);
  cursor: not-allowed;
  opacity: 0.32;
}

.trading-drawing-selection-mode {
  display: contents;
}

.trading-drawing-selection-mode[hidden] {
  display: none !important;
}

.trading-drawing-selection[hidden],
.trading-drawing-selection-popover[hidden] {
  display: none !important;
}

.trading-drawing-selection-grip {
  display: grid;
  width: 16px;
  flex: 0 0 16px;
  grid-template-columns: repeat(2, 2px);
  grid-template-rows: repeat(3, 2px);
  place-content: center;
  gap: 3px;
  border-right: 1px solid var(--trading-market-border);
  cursor: grab;
  touch-action: none;
}

.trading-drawing-selection.dragging .trading-drawing-selection-grip {
  cursor: grabbing;
}

.trading-drawing-selection-grip > i {
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: var(--trading-market-muted);
  opacity: 0.48;
}

.trading-drawing-selection-menu-wrap {
  position: relative;
  display: flex;
}

.trading-drawing-selection-action {
  position: relative;
  display: grid;
  width: 40px;
  min-width: 40px;
  height: 40px;
  place-items: center;
  border: 0;
  border-right: 1px solid var(--trading-market-border);
  border-radius: 0;
  background: transparent;
  color: var(--trading-market-muted);
  padding: 0;
  font: inherit;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease, opacity 0.14s ease;
}

.trading-drawing-selection-mode > .trading-drawing-selection-action:last-child {
  border-right: 0;
  border-radius: 0 5px 5px 0;
}

.trading-drawing-selection-action:hover,
.trading-drawing-selection-action:focus-visible {
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-drawing-selection-action:active,
.trading-drawing-selection-action[aria-expanded="true"],
.trading-drawing-selection-action[aria-pressed="true"] {
  background: var(--trading-market-accent-soft);
  color: var(--trading-market-accent);
}

.trading-drawing-selection-action:disabled {
  background: transparent;
  color: var(--trading-market-muted);
  cursor: not-allowed;
  opacity: 0.32;
}

.trading-drawing-selection-action > svg {
  width: 20px;
  height: 20px;
  overflow: visible;
  fill: none;
  stroke: currentcolor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.25;
}

.trading-drawing-text-symbol,
.trading-drawing-bold-symbol,
.trading-drawing-font-size {
  font-family: "Segoe UI", "Microsoft YaHei", Arial, sans-serif;
  font-size: calc(18px + var(--app-font-size-offset));
  line-height: 1;
}

.trading-drawing-bold-symbol {
  font-weight: 700;
}

.trading-drawing-font-size {
  font-size: calc(14px + var(--app-font-size-offset));
}

.trading-drawing-selection-menu-wrap.font-size > .trading-drawing-selection-action {
  width: 48px;
  min-width: 48px;
}

.trading-drawing-background-symbol {
  display: block;
  width: 17px;
  height: 17px;
  border: 1px solid currentcolor;
  border-radius: 3px;
  background:
    linear-gradient(45deg, color-mix(in srgb, currentcolor 13%, transparent) 25%, transparent 25% 75%, color-mix(in srgb, currentcolor 13%, transparent) 75%),
    linear-gradient(45deg, color-mix(in srgb, currentcolor 13%, transparent) 25%, transparent 25% 75%, color-mix(in srgb, currentcolor 13%, transparent) 75%);
  background-position: 0 0, 4px 4px;
  background-size: 8px 8px;
}

.trading-drawing-line-preview,
.trading-drawing-width-preview {
  display: block;
  width: 24px;
  height: 0;
  border-top: var(--drawing-width, 1px) solid currentcolor;
}

.trading-drawing-line-preview.dashed {
  border-top-style: dashed;
}

.trading-drawing-line-preview.dotted {
  border-top-style: dotted;
}

.trading-drawing-selection-popover {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  z-index: 2;
  width: 246px;
  border: 1px solid var(--trading-market-border);
  border-radius: 7px;
  background: var(--trading-market-panel);
  box-shadow: 0 12px 34px rgba(25, 43, 68, 0.2);
  color: var(--trading-market-text);
  padding: 10px;
  transform: translateX(-50%);
}

.trading-drawing-selection-popover > strong {
  display: block;
  margin: 0 0 8px;
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 600;
}

.trading-drawing-color-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
}

.trading-drawing-color-grid > button {
  display: grid;
  width: 36px;
  height: 26px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  padding: 2px;
  cursor: pointer;
}

.trading-drawing-color-grid > button:hover,
.trading-drawing-color-grid > button:focus-visible {
  border-color: var(--trading-market-muted);
  background: var(--trading-market-control);
}

.trading-drawing-color-grid > button.active,
.trading-drawing-color-grid > button[aria-checked="true"] {
  border-color: var(--trading-market-accent);
  background: var(--trading-market-accent-soft);
}

.trading-drawing-color-grid > button > span {
  display: block;
  width: 28px;
  height: 18px;
  border: 1px solid color-mix(in srgb, var(--drawing-swatch) 70%, var(--trading-market-border));
  border-radius: 3px;
  background: var(--drawing-swatch);
}

.trading-drawing-color-grid > button.transparent > span {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(45deg, #c9cdd3 25%, transparent 25% 75%, #c9cdd3 75%),
    linear-gradient(45deg, #c9cdd3 25%, #ffffff 25% 75%, #c9cdd3 75%);
  background-position: 0 0, 5px 5px;
  background-size: 10px 10px;
}

.trading-drawing-color-grid > button.transparent > span::after {
  position: absolute;
  width: 34px;
  height: 2px;
  background: var(--trading-market-negative);
  content: "";
  transform: rotate(-32deg);
}

.trading-drawing-selection-popover.compact {
  width: 112px;
  padding: 5px;
}

.trading-drawing-selection-popover.compact > button {
  display: grid;
  width: 100%;
  height: 36px;
  place-items: center;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--trading-market-muted);
  cursor: pointer;
}

.trading-drawing-selection-popover.compact > button:hover,
.trading-drawing-selection-popover.compact > button:focus-visible {
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-drawing-selection-popover.compact > button.active,
.trading-drawing-selection-popover.compact > button[aria-checked="true"] {
  background: var(--trading-market-accent-soft);
  color: var(--trading-market-accent);
}

.trading-drawing-selection-popover.compact.font-size {
  width: 84px;
  max-height: 350px;
  overflow-y: auto;
}

.trading-drawing-selection-popover.text-input {
  left: 0;
  width: 360px;
  overflow: hidden;
  padding: 0;
  transform: none;
}

.trading-drawing-selection-popover.text-input > header {
  display: flex;
  height: 40px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--trading-market-border);
  padding: 0 8px 0 12px;
}

.trading-drawing-selection-popover.text-input > header strong {
  color: var(--trading-market-text);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 500;
}

.trading-drawing-selection-popover.text-input > header .trading-drawing-selection-action {
  width: 30px;
  min-width: 30px;
  height: 30px;
  border: 0;
  border-radius: 4px;
  font-size: calc(23px + var(--app-font-size-offset));
  font-weight: 300;
}

.trading-drawing-selection-popover.text-input textarea {
  display: block;
  width: calc(100% - 24px);
  min-height: 138px;
  max-height: 260px;
  margin: 12px;
  resize: vertical;
  border: 1px solid transparent;
  border-radius: 4px;
  outline: 0;
  background: var(--trading-market-control);
  color: var(--trading-market-text);
  padding: 12px;
  font: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
  line-height: 1.55;
  user-select: text;
  -webkit-user-select: text;
  transition: border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.trading-drawing-selection-popover.text-input textarea:hover {
  background: var(--trading-market-control-hover);
}

.trading-drawing-selection-popover.text-input textarea:focus {
  border-color: var(--trading-market-accent);
  background: var(--trading-market-bg);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--trading-market-accent) 18%, transparent);
}

.trading-drawing-selection-popover.text-input textarea::placeholder {
  color: var(--text-placeholder);
}

.trading-drawing-selection-popover.text-input > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  border-top: 1px solid var(--trading-market-border);
  padding: 10px 12px;
}

.trading-drawing-selection-popover.text-input > footer button {
  min-width: 72px;
  height: 32px;
  border: 1px solid var(--trading-market-border);
  border-radius: 4px;
  background: var(--trading-market-panel);
  color: var(--trading-market-text);
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
  cursor: pointer;
  transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease, opacity 0.14s ease;
}

.trading-drawing-selection-popover.text-input > footer button.primary {
  border-color: var(--trading-market-accent);
  background: var(--trading-market-accent);
  color: #ffffff;
}

.trading-drawing-selection-popover.text-input > footer button:hover,
.trading-drawing-selection-popover.text-input > footer button:focus-visible {
  border-color: var(--trading-market-accent);
  background: var(--trading-market-accent-soft);
  color: var(--trading-market-accent);
  outline: 0;
}

.trading-drawing-selection-popover.text-input > footer button.primary:hover,
.trading-drawing-selection-popover.text-input > footer button.primary:focus-visible {
  background: color-mix(in srgb, var(--trading-market-accent) 84%, #000000);
  color: #ffffff;
}

.trading-drawing-selection-popover.text-input > footer button:active {
  transform: translateY(1px);
}

.trading-drawing-selection-popover.text-input > footer button:disabled {
  cursor: not-allowed;
  opacity: 0.38;
  transform: none;
}

html[data-theme="dark"] .trading-drawing-color-grid > button.transparent > span {
  background:
    linear-gradient(45deg, #4b5563 25%, transparent 25% 75%, #4b5563 75%),
    linear-gradient(45deg, #4b5563 25%, #242a33 25% 75%, #4b5563 75%);
  background-position: 0 0, 5px 5px;
  background-size: 10px 10px;
}

.trading-market-period-controls {
