.trading-market-categories button:focus-visible {
  outline: 2px solid var(--trading-market-accent);
  outline-offset: 1px;
}

.trading-market-categories button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.trading-market-picker-head,
.trading-market-row {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(0, 1fr) minmax(0, 1fr) minmax(0, 0.8fr) 32px;
  align-items: center;
  gap: 12px;
}

.trading-market-picker-head {
  min-width: 0;
  height: 38px;
  flex: 0 0 auto;
  border-bottom: 1px solid var(--trading-market-border);
  color: var(--trading-market-muted);
  padding: 0 20px 0 12px;
  font-size: calc(11px + var(--app-font-size-offset));
}

.trading-market-picker-head > *,
.trading-market-row > .trading-market-row-pair,
.trading-market-row > .trading-market-row-venue,
.trading-market-row > b,
.trading-market-row > em {
