  justify-self: stretch;
  text-align: left;
}

.trading-market-picker-head > :nth-child(3),
.trading-market-picker-head > :nth-child(4),
.trading-market-row > b,
.trading-market-row > em {
  transform: translateX(-13px);
}

.trading-market-picker-head > :last-child {
