}

.trading-market-row {
  position: relative;
  width: 100%;
  min-width: 0;
  min-height: 44px;
  border-bottom: 1px solid color-mix(in srgb, var(--trading-market-border) 68%, transparent);
  color: var(--trading-market-text);
  padding: 5px 7px;
}

.trading-market-row-select {
  position: absolute;
  inset: 0;
  z-index: 0;
  border: 0;
  border-radius: 0;
