  overflow: hidden;
  color: var(--trading-market-muted);
  font-size: calc(10px + var(--app-font-size-offset));
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trading-market-row > b,
.trading-market-row > em {
  overflow: hidden;
  font-size: calc(11px + var(--app-font-size-offset));
  font-style: normal;
  font-weight: 500;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trading-market-favorite {
  position: relative;
  z-index: 2;
  display: inline-grid;
  width: 28px;
  height: 28px;
  place-items: center;
  justify-self: center;
