  fill: transparent;
  stroke: currentColor;
  stroke-linejoin: round;
  stroke-width: 1.7;
  transition: fill 0.14s ease, stroke 0.14s ease;
}

.trading-market-favorite:hover {
  background: transparent;
  color: var(--trading-market-favorite-fill);
}

.trading-market-favorite.active {
  background: transparent;
  color: var(--trading-market-favorite-fill);
}

.trading-market-favorite.active > svg {
  fill: currentColor;
}

.trading-market-favorite.active:hover {
  background: transparent;
}

.trading-market-favorite:active {
  transform: scale(0.92);
}

.trading-market-favorite:focus-visible {
  outline: 2px solid var(--trading-market-favorite-fill);
  outline-offset: 1px;
}

.trading-market-favorite:disabled {
  cursor: not-allowed;
  opacity: 0.45;
  transform: none;
}

.trading-market-list-empty {
