  z-index: 126;
  inset: 0;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, #101828 40%, transparent);
  padding: 20px;
  backdrop-filter: blur(2px);
}

.trading-chart-settings-dialog {
  display: grid;
  width: min(910px, calc(100% - 30px));
  height: min(620px, calc(100% - 30px));
  min-width: 600px;
  min-height: 430px;
  grid-template-rows: 62px minmax(0, 1fr) 56px;
  overflow: hidden;
  border: 1px solid var(--trading-market-border);
  border-radius: 9px;
  background: var(--trading-market-panel);
  box-shadow: 0 28px 86px rgba(17, 24, 39, 0.28);
  color: var(--trading-market-text);
}

.trading-chart-settings-dialog > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--trading-market-border);
  padding: 0 22px 0 28px;
}

.trading-chart-settings-dialog > header strong {
  font-size: calc(17px + var(--app-font-size-offset));
  font-weight: 650;
}

.trading-chart-settings-dialog > header button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--trading-market-muted);
  cursor: pointer;
}

.trading-chart-settings-dialog > header button:hover,
.trading-chart-settings-dialog > footer button:hover {
  background: var(--trading-market-control);
  color: var(--trading-market-text);
}

.trading-chart-settings-dialog > header button:active,
.trading-chart-settings-dialog > footer button:active {
  background: var(--trading-market-control-hover);
}

.trading-chart-settings-dialog > header button svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 1.5;
}

.trading-chart-settings-body {
  display: grid;
  min-height: 0;
  grid-template-columns: 180px minmax(0, 1fr);
}

.trading-chart-settings-body > nav {
  display: grid;
  min-height: 0;
  align-content: start;
  gap: 2px;
  overflow-y: auto;
  border-right: 1px solid var(--trading-market-border);
  background: color-mix(in srgb, var(--trading-market-control) 42%, var(--trading-market-panel));
  padding: 10px 0;
}

.trading-chart-settings-body > nav button {
  position: relative;
  height: 48px;
  border: 0;
  background: transparent;
  color: var(--trading-market-text);
  cursor: pointer;
  padding: 0 28px;
  font: inherit;
  font-size: calc(13px + var(--app-font-size-offset));
  text-align: left;
}

.trading-chart-settings-body > nav button:hover {
  background: var(--trading-market-control);
}

.trading-chart-settings-body > nav button.selected {
  background: var(--trading-market-control-hover);
  color: var(--trading-market-accent);
}

.trading-chart-settings-body > nav button.selected::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  background: var(--trading-market-accent);
  content: "";
}

.trading-chart-settings-body > nav button:focus-visible,
.trading-chart-settings-dialog input:focus-visible,
.trading-chart-settings-dialog > header button:focus-visible,
.trading-chart-settings-dialog > footer button:focus-visible {
  outline: 2px solid var(--trading-market-accent);
  outline-offset: -2px;
}

.trading-chart-settings-body > main {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  padding: 22px 30px 32px;
}

.trading-chart-settings-body > main > section {
  display: grid;
  align-content: start;
  gap: 22px;
}

.trading-chart-settings-body > main > section[hidden] {
  display: none !important;
}

.trading-chart-settings-row {
  display: grid;
  min-height: 34px;
  grid-template-columns: 96px minmax(0, 1fr);
  align-items: start;
  gap: 10px 0;
  color: var(--trading-market-text);
  font-size: calc(13px + var(--app-font-size-offset));
}

.trading-chart-settings-row > span {
  padding-top: 7px;
  color: var(--trading-market-muted);
}

.trading-chart-settings-row > small {
  grid-column: 2;
  color: var(--trading-market-muted);
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 17px;
}

.trading-chart-settings-options {
  display: flex;
  min-width: 0;
  min-height: 34px;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 24px;
}

.trading-chart-settings-options.vertical {
  display: grid;
  justify-items: start;
  gap: 16px;
}

.trading-chart-settings-choice,
.trading-chart-settings-check {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  gap: 8px;
  color: var(--trading-market-text);
  cursor: pointer;
  line-height: 20px;
  user-select: none;
}

.trading-chart-settings-choice input,
.trading-chart-settings-check input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.trading-chart-settings-choice > span {
  display: grid;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--trading-market-muted) 60%, var(--trading-market-border));
  border-radius: 50%;
  background: var(--trading-market-panel);
}

.trading-chart-settings-choice input:checked + span {
  border: 5px solid var(--trading-market-accent);
}

.trading-chart-settings-check > span {
  display: grid;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--trading-market-muted) 60%, var(--trading-market-border));
  border-radius: 2px;
  background: var(--trading-market-panel);
  color: #ffffff;
}

.trading-chart-settings-check input:checked + span {
  border-color: var(--trading-market-accent);
  background: var(--trading-market-accent);
}

.trading-chart-settings-check input:checked + span::after {
  width: 7px;
  height: 4px;
  border-bottom: 1.5px solid currentColor;
  border-left: 1.5px solid currentColor;
  content: "";
  transform: translateY(-1px) rotate(-45deg);
}

.trading-chart-settings-choice:hover,
.trading-chart-settings-check:hover {
  color: var(--trading-market-accent);
}

.trading-chart-settings-choice input:focus-visible + span,
.trading-chart-settings-check input:focus-visible + span {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--trading-market-accent) 24%, transparent);
}

.trading-chart-settings-choice.disabled,
.trading-chart-settings-choice:has(input:disabled),
.trading-chart-settings-check:has(input:disabled) {
  cursor: not-allowed;
  opacity: 0.45;
}

.trading-chart-settings-color {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  gap: 7px;
  color: var(--trading-market-muted);
  cursor: pointer;
  font-size: calc(11px + var(--app-font-size-offset));
}

.trading-chart-settings-color input {
  width: 26px;
  height: 24px;
  overflow: hidden;
  border: 1px solid var(--trading-market-border);
  border-radius: 3px;
  background: transparent;
  cursor: pointer;
  padding: 0;
}

.trading-chart-settings-color input::-webkit-color-swatch-wrapper {
  padding: 2px;
}

.trading-chart-settings-color input::-webkit-color-swatch {
  border: 0;
  border-radius: 1px;
}

.trading-chart-settings-number {
  display: inline-flex;
  width: 70px;
  height: 32px;
  align-items: center;
  border: 1px solid var(--trading-market-border);
  border-radius: 4px;
  background: var(--trading-market-panel);
}

.trading-chart-settings-number:focus-within,
.trading-chart-settings-number:hover {
  border-color: var(--trading-market-accent);
}

.trading-chart-settings-number input {
  width: 46px;
  height: 30px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--trading-market-text);
  padding: 0 3px 0 9px;
  font: inherit;
}

.trading-chart-settings-number b {
  color: var(--trading-market-muted);
  font-weight: 400;
}

.trading-chart-settings-line-preview {
  display: block;
  width: 88px;
  border-top: 1px solid var(--trading-market-muted);
}

.trading-chart-settings-line-preview.dashed {
  border-top-style: dashed;
}

.trading-chart-settings-theme-note {
  margin: 12px 0 0 96px;
  color: var(--trading-market-muted);
  font-size: calc(11px + var(--app-font-size-offset));
}

.trading-chart-order-display-list {
  display: grid;
  max-width: 560px;
  gap: 22px;
}

.trading-chart-order-display-row {
  display: grid;
  min-height: 34px;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 24px;
  padding: 0;
}

.trading-chart-order-display-copy {
  min-width: 0;
}

.trading-chart-order-display-copy strong {
  display: block;
  padding-top: 7px;
  color: var(--trading-market-muted);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 20px;
}

.trading-chart-settings-switch {
  position: relative;
  display: inline-flex;
  width: 36px;
  height: 20px;
  flex: 0 0 36px;
  align-items: center;
  margin-top: 7px;
  cursor: pointer;
}

.trading-chart-settings-switch input {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
  opacity: 0;
}

.trading-chart-settings-switch > span {
  position: relative;
  display: block;
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: var(--trading-chart-switch-off);
  transition: background-color 140ms ease, box-shadow 140ms ease;
}

.trading-chart-settings-switch > span::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--trading-chart-switch-knob);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--trading-market-text) 28%, transparent);
  content: "";
  transform: translateX(0);
  transition: transform 140ms ease, scale 90ms ease;
}

.trading-chart-settings-switch input:checked + span {
  background: var(--trading-chart-switch-on);
}

.trading-chart-settings-switch input:checked + span::after {
  transform: translateX(16px);
}

.trading-chart-settings-switch:hover input:not(:disabled) + span {
  background: var(--trading-chart-switch-off-hover);
}

.trading-chart-settings-switch:hover input:checked:not(:disabled) + span {
  background: var(--trading-chart-switch-on-hover);
}

.trading-chart-settings-switch:active input:not(:disabled) + span::after {
  scale: 0.9;
}

.trading-chart-settings-switch input:focus-visible + span {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--trading-market-accent) 28%, transparent);
}

.trading-chart-settings-switch:has(input:disabled) {
  cursor: not-allowed;
  opacity: 0.45;
}

.trading-chart-settings-switch input:disabled {
  cursor: not-allowed;
}

.trading-chart-settings-dialog > footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  border-top: 1px solid var(--trading-market-border);
  padding: 0 28px;
}

.trading-chart-settings-dialog > footer button {
  height: 34px;
  border: 1px solid var(--trading-market-border);
  border-radius: 4px;
  background: var(--trading-market-control);
  color: var(--trading-market-text);
  cursor: pointer;
  padding: 0 15px;
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
}

.trading-chart-settings-dialog > footer button:disabled,
.trading-chart-settings-dialog > header button:disabled,
.trading-chart-settings-color input:disabled,
.trading-chart-settings-number input:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.trading-expert-market.drawing-tools-disabled .trading-drawing-toolbar {
  display: none !important;
}

.trading-expert-market.drawing-tools-disabled .trading-market-indicator-bar {
  width: 100%;
  margin-left: 0;
}

.trading-expert-market.drawing-tools-disabled .trading-drawing-layer [data-drawing-content] {
  pointer-events: none;
}

.trading-expert-market.drawing-tools-disabled [data-ai-text-hit-content],
.trading-expert-market.drawing-tools-disabled .trading-ai-text-size-toolbar {
  display: none !important;
}

.trading-expert-market.drawing-tools-disabled .trading-drawing-selection {
  display: none !important;
}

