/* Codex-like conversation history: one quiet sentence per existing task while
   keeping the original row events, status indicators, and overflow actions. */
.conversation-row-wrap.conversation-row-minimal {
  width: calc(100% - 12px);
  height: 32px;
  margin: 0 6px;
  border-radius: 7px;
}

.conversation-section
  > .conversation-row-minimal
  + .conversation-row-minimal {
  margin-top: 2px;
}

.conversation-row-wrap.conversation-row-minimal .conversation-row {
  gap: 0;
  padding: 0 12px;
}

.conversation-row-wrap.conversation-row-minimal.has-final-result-unviewed
  .conversation-row {
  padding-right: 28px;
}

.conversation-row-wrap.conversation-row-minimal:is(
    :hover,
    :focus-within,
    .menu-open,
    .has-unread,
    .is-working
  )
  .conversation-row {
  padding-right: 36px;
}

.conversation-row-wrap.conversation-row-minimal.has-unread.is-working
  .conversation-row {
  padding-right: 54px;
}

.conversation-row-minimal .conversation-copy-minimal,
.conversation-row-minimal .conversation-copy-minimal .row-title,
.conversation-row-minimal .conversation-copy-minimal .row-name {
  display: block;
  min-width: 0;
  width: 100%;
}

.conversation-row-minimal .conversation-copy-minimal .row-title {
  display: flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
}

.conversation-row-minimal .thread-marker-dot {
  position: absolute;
  top: 50%;
  left: -2px;
  width: 7px;
  height: 7px;
  transform: translateY(-50%);
  pointer-events: none;
}

.conversation-row-minimal .conversation-analysis-context {
  flex: 0 0 auto;
  color: var(--conversation-analysis-context);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 650;
  line-height: 20px;
  white-space: nowrap;
}

.conversation-row-minimal .conversation-copy-minimal .row-name {
  position: relative;
  flex: 1 1 auto;
  container-type: inline-size;
  overflow: hidden;
  color: var(--text-primary);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 20px;
  text-overflow: clip;
  white-space: nowrap;
  -webkit-mask-image: linear-gradient(
    to right,
    black 0,
    black calc(100% - 12px),
    color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
    color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to right,
    black 0,
    black calc(100% - 12px),
    color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
    color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
    transparent 100%
  );
}

.conversation-row-minimal .row-name-text {
  display: inline-block;
  width: max-content;
  min-width: max-content;
  overflow: visible;
  text-overflow: clip;
  transform: translateX(0);
  white-space: nowrap;
}

.conversation-row-wrap.conversation-row-minimal:is(
    :hover,
    :focus-within,
    .menu-open
  )
  .row-name {
  -webkit-mask-image: linear-gradient(
    to right,
    transparent 0,
    color-mix(in srgb, black 48%, transparent) 3px,
    color-mix(in srgb, black 82%, transparent) 7px,
    black 10px,
    black calc(100% - 12px),
    color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
    color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to right,
    transparent 0,
    color-mix(in srgb, black 48%, transparent) 3px,
    color-mix(in srgb, black 82%, transparent) 7px,
    black 10px,
    black calc(100% - 12px),
    color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
    color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
    transparent 100%
  );
}

.conversation-row-wrap.conversation-row-minimal:is(
    :hover,
    :focus-within,
    .menu-open
  )
  .row-name-text {
  animation: conversation-title-scroll-left 2s ease-in-out 0.2s both;
  will-change: transform;
}

@keyframes conversation-title-scroll-left {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(min(0px, calc(100cqw - 100%)));
  }
}

@media (prefers-reduced-motion: reduce) {
  .conversation-row-wrap.conversation-row-minimal:is(
      :hover,
      :focus-within,
      .menu-open
    )
    .row-name {
    -webkit-mask-image: linear-gradient(
      to right,
      black 0,
      black calc(100% - 12px),
      color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
      color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
      transparent 100%
    );
    mask-image: linear-gradient(
      to right,
      black 0,
      black calc(100% - 12px),
      color-mix(in srgb, black 82%, transparent) calc(100% - 8px),
      color-mix(in srgb, black 48%, transparent) calc(100% - 3px),
      transparent 100%
    );
  }

  .conversation-row-wrap.conversation-row-minimal:is(
      :hover,
      :focus-within,
      .menu-open
    )
    .row-name-text {
    animation: none;
    transform: translateX(0);
  }
}

.conversation-row-wrap.conversation-row-minimal .thread-more-button {
  right: 4px;
  width: 28px;
  height: 28px;
}

.conversation-row-wrap.conversation-row-minimal .unread-dot {
  top: 8px;
  right: 10px;
}

.conversation-row-wrap.conversation-row-minimal.has-unread
  .conversation-row-spinner {
  right: 32px;
}

.conversation-row-wrap.conversation-row-minimal.has-final-result-unviewed:not(
    .has-unread
  ):not(.is-working)::after {
  position: absolute;
  top: 50%;
  right: 13px;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--brand-blue);
  content: "";
  pointer-events: none;
  transform: translateY(-50%);
}

.conversation-row-wrap.conversation-row-minimal.has-final-result-unviewed:is(
    :hover,
    .menu-open
  )::after,
.conversation-row-wrap.conversation-row-minimal:not(.is-working):is(
    :hover,
    .menu-open
  )
  .unread-dot {
  opacity: 0;
}

html
  .conversation-row-wrap.conversation-row-minimal:not(.active):is(
    :hover,
    :focus-within,
    .menu-open
  ) {
  background: var(--surface-hover-translucent);
}

html .conversation-row-wrap.conversation-row-minimal.active {
  background: var(--conversation-row-selected);
  box-shadow: none;
}

html
  .conversation-row-wrap.conversation-row-minimal.active
  .conversation-copy-minimal
  .row-name {
  color: var(--text-primary);
}

.conversation-row-wrap.conversation-row-minimal .conversation-row:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 1px var(--border-translucent);
}

.conversation-row-wrap.conversation-row-minimal .conversation-row:active {
  background: var(--surface-hover-translucent);
}

.conversation-row-wrap.conversation-row-minimal
  .thread-more-button:is(:hover, :focus-visible, .active) {
  background: var(--surface-hover-translucent);
  color: var(--text-primary);
}

/* Codex-like sidebar architecture: sticky new-conversation entry, direct tools,
   one global pinned list, then folder-based projects. All states use shared
   surface tokens so light and dark themes stay visually equivalent. */
.conversation-list-new-sticky,
.conversation-list-secondary-actions,
.conversation-list-heading {
  margin-right: 5px;
  margin-left: -5px;
}

.conversation-list-new-sticky {
  position: sticky;
  top: 0;
  z-index: 12;
  padding: 0 6px;
  background: var(--app-chrome-background);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.conversation-list-new-row {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
}

.conversation-list-action {
  display: flex;
  width: 100%;
  height: 32px;
  min-width: 0;
  align-items: center;
  gap: 10px;
  border-radius: 7px;
  padding: 0 12px;
  background: transparent;
  color: var(--text-primary);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 20px;
  text-align: left;
}

.conversation-list-action > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.conversation-list-action:is(:hover, :focus-visible) {
  background: var(--conversation-action-hover);
}

.conversation-list-action.active,
.conversation-list-action:active {
  background: var(--conversation-action-hover);
}

.conversation-list-new-action.active {
  background: transparent;
}

.conversation-list-new-action.active:is(:hover, :focus-visible),
.conversation-list-new-action:active {
  background: var(--conversation-action-hover);
}

.conversation-list-new-action {
  width: auto;
  flex: 1 1 auto;
}

.conversation-list-action:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 1px var(--conversation-action-focus);
}

.conversation-list-action:disabled {
  background: transparent;
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: 0.58;
}

.conversation-list-icon {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  color: currentColor;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.65;
}

.conversation-list-secondary-actions {
  display: grid;
  gap: 0;
  padding: 0 6px 10px;
}

.conversation-list-heading {
  display: flex;
  height: 32px;
  align-items: center;
  padding: 0 18px;
  color: var(--text-tertiary);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: 18px;
}

.conversation-pinned-section,
.conversation-projects-section {
  padding-top: 6px;
}

.conversation-project-section {
  position: relative;
  left: -6px;
  padding-top: 0;
}

.conversation-project-section .conversation-group-title {
  position: relative;
  left: 2px;
  width: calc(100% - 12px);
  height: 32px;
  margin: 0 6px;
  border-radius: 7px;
  padding: 0;
}

.conversation-project-section .conversation-group-title:is(:hover, .menu-open) {
  background: var(--surface-hover-translucent);
}

.conversation-project-section .conversation-group-toggle {
  width: 100%;
  height: 32px;
  gap: 9px;
  border-radius: 7px;
  padding: 0 12px;
  color: var(--text-primary);
  font-size: calc(13px + var(--app-font-size-offset));
  font-weight: 400;
}

.conversation-project-section .conversation-group-toggle:hover {
  background: transparent;
}

.conversation-project-section .conversation-group-toggle-static {
  display: flex;
}

.conversation-project-section .thread-group-more-button:is(:hover, :focus-visible, .active) {
  background: var(--surface-hover-translucent);
  color: var(--text-primary);
}

.conversation-project-thread-list > .conversation-row-wrap.conversation-row-minimal {
  /* Keep the wider row width while shifting the whole conversation group 3px left. */
  width: calc(100% - 19px);
  margin-right: 4px;
  margin-left: 15px;
}

.conversation-project-thread-list
  > .conversation-row-wrap.conversation-row-minimal
  + .conversation-row-wrap.conversation-row-minimal {
  margin-top: 2px;
}

.conversation-project-expand {
  display: flex;
  width: calc(100% - 19px);
  height: 32px;
  margin: 0 4px 0 15px;
  align-items: center;
  justify-content: flex-start;
  border-radius: 7px;
  padding: 7px 12px;
  color: var(--text-tertiary);
  font-size: calc(12px + var(--app-font-size-offset));
  line-height: 18px;
  text-align: left;
}

.conversation-project-expand:is(:hover, :focus-visible) {
  background: var(--surface-hover-translucent);
  color: var(--text-secondary);
}

.conversation-project-expand:active {
  background: var(--surface-active-translucent);
}

.conversation-project-expand:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 1px var(--border-translucent);
}

.conversation-project-expand:disabled {
  background: transparent;
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: 0.58;
}

html[data-theme="dark"]
  .conversation-row-wrap.conversation-row-minimal:not(.active):is(
    :hover,
    :focus-within,
    .menu-open
  ),
html[data-theme="dark"]
  .conversation-project-section
  .conversation-group-title:is(:hover, .menu-open) {
  background: var(--surface-hover-translucent);
}

html[data-theme="dark"] .conversation-row-wrap.conversation-row-minimal.active {
  background: var(--conversation-row-selected);
}

/* Saved and in-chat execution plans share one semantic palette in both themes. */
.execution-plans-page,
.message-execution-plan {
  --execution-plan-direction-bullish: #078c53;
  --execution-plan-direction-bearish: #d63857;
}

.execution-plans-page {
  position: relative;
  z-index: 2;
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  box-sizing: border-box;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text-primary);
