}

.message-execution-plan-context.after {
  margin-top: 16px;
}

.execution-plan-card-status {
  position: absolute;
  top: 2px;
  right: 0;
  max-width: 62px;
  overflow: hidden;
  color: var(--text-muted);
  font-size: calc(11px + var(--app-font-size-offset));
  font-weight: 500;
  line-height: max(16px, 1.5em);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.execution-plan-card-status.pending {
  color: var(--conversation-analysis-context);
}

.execution-plan-card-status:is(.executing, .take-profit) {
  color: var(--execution-plan-direction-bullish);
}

.execution-plan-card-status.stop-loss {
  color: var(--execution-plan-direction-bearish);
}

.execution-plan-card-content {
  display: grid;
  gap: 3px;
  color: var(--text-secondary);
  font-size: calc(12px + var(--app-font-size-offset));
