}

.message-execution-plan .execution-plan-card-content {
  font-size: calc(var(--message-execution-plan-font-size) + var(--app-font-size-offset));
}

.execution-plan-card-line {
  margin: 0;
  padding: 0;
  text-align: left;
}

.execution-plan-card-label {
  color: var(--conversation-analysis-context);
  font-weight: 700;
}

.execution-plan-card-value-bearish {
  color: var(--execution-plan-direction-bearish);
}

.execution-plan-card-value-bullish {
  color: var(--execution-plan-direction-bullish);
}

.execution-plan-card-number-bearish {
  color: var(--execution-plan-direction-bearish);
}

.execution-plan-card-number-bullish {
  color: var(--execution-plan-direction-bullish);
}

.message-execution-plan-controls {
  position: absolute;
