  border-radius: 5px;
  background: transparent;
  padding: 2px 3px;
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
  font-size: calc(10px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 16px;
  transition: background-color 120ms ease, color 120ms ease, opacity 120ms ease;
}

.message-execution-plan-controls button:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.message-execution-plan-controls button:active:not(:disabled) {
  background: var(--surface-active-translucent);
  color: var(--text-primary);
}

.message-execution-plan-controls button:focus-visible {
