}

.execution-plan-card-actions {
  position: absolute;
  z-index: 2;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1px;
  border-radius: 7px;
  background: color-mix(in srgb, var(--surface-primary) 94%, transparent);
