  pointer-events: none;
  transition: opacity 140ms ease;
}

.execution-plan-card:is(:hover, :focus-within) .execution-plan-card-actions,
.execution-plan-card-actions.open {
  opacity: 1;
  pointer-events: auto;
}

.execution-plan-card:is(:hover, :focus-within) footer time,
.execution-plan-card:has(.execution-plan-card-actions.open) footer time {
  opacity: 0;
}

.execution-plan-card-actions button,
.execution-plan-end-menu button {
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font-family: inherit;
  font-size: calc(10px + var(--app-font-size-offset));
  line-height: 16px;
}

.execution-plan-card-actions button {
  padding: 4px 6px;
}

.execution-plan-card-actions button:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.execution-plan-card-actions button:active {
  background: var(--surface-active-translucent);
}

.execution-plan-card-actions button:focus-visible,
.execution-plan-end-menu button:focus-visible,
