  outline-offset: 2px;
}

.execution-plan-card-actions button:disabled {
  background: transparent;
  color: var(--text-muted);
  cursor: not-allowed;
  opacity: .52;
}

.execution-plan-end-menu {
  position: absolute;
  z-index: 5;
  right: 12px;
  bottom: 43px;
  display: grid;
  min-width: 108px;
  gap: 2px;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: var(--surface-primary);
  padding: 5px;
  box-shadow: var(--page-home-button-shadow);
}

.execution-plan-end-menu button {
  width: 100%;
  padding: 6px 9px;
  text-align: left;
}

.execution-plan-end-menu button:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.execution-plan-end-menu button:active {
  background: var(--surface-active-translucent);
}

.execution-plan-end-menu button.take-profit {
  color: var(--execution-plan-direction-bullish);
}

.execution-plan-end-menu button.stop-loss {
  color: var(--execution-plan-direction-bearish);
}

.execution-plan-end-menu button.cancel {
  border-top: 1px solid var(--border-subtle);
  border-radius: 0 0 6px 6px;
  margin-top: 2px;
}

.execution-plan-empty {
  display: grid;
  min-height: 0;
  flex: 1 1 auto;
  place-items: center;
  padding-bottom: 10vh;
}

.execution-plan-empty p {
  margin: 0;
  color: var(--text-muted);
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 400;
  line-height: 18px;
}

html[data-theme="dark"] :is(.execution-plans-page, .message-execution-plan) {
  --execution-plan-direction-bullish: #52dc88;
  --execution-plan-direction-bearish: #ff718e;
}

html[data-theme="dark"] .execution-plans-page {
