  background: var(--surface-hover-translucent);
}

html[data-theme="dark"] .message-execution-plan {
  border-color: var(--card-border-subtle);
  background: var(--surface-primary);
}

html[data-theme="dark"] .message-execution-plan:hover {
  border-color: color-mix(in srgb, var(--text-primary) 15%, transparent);
  background: var(--surface-hover-translucent);
}

html[data-theme="dark"] .message-execution-plan-controls button:hover:not(:disabled) {
  background: var(--surface-hover-translucent);
  color: var(--text-primary);
}

html[data-theme="dark"] .message-execution-plan-controls button:active:not(:disabled) {
  background: var(--surface-active-translucent);
}

html[data-theme="dark"] .message-execution-plan-controls button:focus-visible {
  outline-color: var(--brand-blue);
  color: var(--text-primary);
}

html[data-theme="dark"] .message-execution-plan-controls button:disabled,
html[data-theme="dark"] .message-execution-plan-controls button[aria-busy="true"] {
