}

html[data-theme="dark"] .message-execution-plan-controls {
  background: color-mix(in srgb, var(--surface-primary) 92%, transparent);
}

html[data-theme="dark"] .execution-plan-card-actions {
  background: color-mix(in srgb, var(--surface-primary) 90%, transparent);
}

html[data-theme="dark"] .execution-plan-end-menu {
