@media (hover: none) {
  .execution-plan-card-actions {
    opacity: 1;
    pointer-events: auto;
  }

  .execution-plan-card footer time {
    opacity: 0;
  }
}

@media (max-width: 980px) {
  .execution-plan-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 660px) {
  .execution-plan-list {
    width: calc(100% - 40px);
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .execution-plan-card,
  .execution-plan-card-actions,
  .message-execution-plan,
  .message-execution-plan-controls,
  .message-execution-plan-controls button,
  .execution-plan-card footer time {
