  --binance-text-muted: #8b929c;
  --binance-action: #15171b;
  --binance-action-hover: #292c31;
  --binance-action-active: #050607;
  --binance-action-text: #ffffff;
  --binance-positive: #0a9d68;
  --binance-negative: #e8465b;
  --binance-calendar-profit-bg: #e6f6ed;
