  --binance-calendar-loss-bg: #fff0f2;
  --binance-calendar-loss-text: #cc354b;
  --binance-calendar-neutral-bg: #ffffff;
  --binance-calendar-cell-border: #dfe4ea;
  --binance-danger-action: #c62842;
  --binance-danger-action-hover: #b51e37;
