  --binance-history-scrollbar-thumb: rgba(120, 129, 143, 0.42);
  --binance-history-scrollbar-thumb-hover: rgba(82, 92, 107, 0.68);
  --binance-shadow: 0 18px 54px rgba(20, 24, 32, 0.15);
