  --binance-label-text: #f4f5f7;
  --binance-text-secondary: #b7bdc7;
  --binance-text-muted: #858d99;
  --binance-action: #f4f5f7;
  --binance-action-hover: #ffffff;
  --binance-action-active: #d8dbe0;
  --binance-action-text: #101216;
  --binance-positive: #27c894;
  --binance-negative: #ff5f73;
