.desktop-body > .binance-account-page {
  position: relative;
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-direction: column;
  overflow: hidden;
  background: var(--binance-bg);
  color: var(--binance-text);
  box-shadow: -1px 0 0 var(--binance-border);
}

html[data-theme="dark"] .desktop-body > .binance-account-page {
  background: var(--binance-bg);
  box-shadow: -1px 0 0 var(--binance-border);
}

/* Every central workspace keeps the same inset corner, independent of the
   active navigation destination or native window maximization state. */
.desktop-body > :is(
  .chat-panel,
  .trading-expert-chat-panel,
  .binance-account-page,
  .trading-alerts-page,
  .execution-plans-page,
  .auto-task-page,
  .skills-plaza-page,
  .library-page
) {
  border-top-left-radius: 16px;
}

/* The New Task ticker rail and market canvas form one continuous surface.
   Other workspaces keep the shared 16px inset corner above. */
.desktop-shell:has(.titlebar-market-favorites-host:not([hidden]))
  > .desktop-body.trading-expert-layout
  > .trading-expert-chat-panel {
  border-top-left-radius: 0;
}

/* The rounded page must reveal the app chrome beneath it. The default body
   uses a nearly-white gradient, which visually fills the clipped corner and
   makes the 16px radius look like a protruding square in light mode. */
html[data-theme] .desktop-body:has(> :is(
  .trading-alerts-page,
  .execution-plans-page,
  .skills-plaza-page
)) {
  background: var(--app-chrome-background);
}

/* Alerts and Skills keep the inset workspace corner even when the native
   window is maximized. These selectors intentionally outrank the generic
   maximized-page reset above, while sharing the same rule in both themes. */
.window-maximized .desktop-body > :is(
  .trading-alerts-page,
  .execution-plans-page,
  .skills-plaza-page
) {
  border-top-left-radius: 16px;
}

.binance-account-quiet-button,
.binance-account-bind-button,
.binance-account-tutorial-button,
.binance-account-submit {
  min-height: 36px;
  border: 1px solid var(--binance-border);
  border-radius: 8px;
  background: var(--binance-surface);
  padding: 0 14px;
  color: var(--binance-text);
  font: inherit;
  font-size: calc(12px + var(--app-font-size-offset));
