}

.binance-account-quiet-button:hover:not(:disabled),
.binance-account-tutorial-button:hover:not(:disabled) { border-color: var(--binance-border-strong); background: var(--binance-surface-hover); }
.binance-account-quiet-button:active:not(:disabled),
