.binance-account-quiet-button.danger { color: var(--binance-negative); }
.binance-account-quiet-button.danger:hover:not(:disabled) { border-color: color-mix(in srgb, var(--binance-negative) 38%, var(--binance-border)); background: var(--binance-danger-bg); }

.binance-account-bound-view {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  overflow: hidden;
  padding: 30px 0 0;
}

.binance-account-toolbar {
  display: flex;
  width: min(1180px, calc(100% - 68px));
