.binance-account-toolbar-actions {
  display: flex;
  min-width: 0;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  margin-right: 8px;
}

.binance-account-scroll {
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-color: var(--binance-border-strong) transparent;
}

.binance-account-scroll.history {
  scrollbar-color: transparent transparent;
}

.binance-account-scroll.history::-webkit-scrollbar-thumb {
  background-color: transparent;
}

.binance-account-scroll.history::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}

.binance-account-scroll.history:hover,
.binance-account-scroll.history:focus-visible {
  outline: 0;
