}

.binance-account-scroll.history:hover::-webkit-scrollbar-thumb,
.binance-account-scroll.history:focus-visible::-webkit-scrollbar-thumb {
  background-color: var(--binance-history-scrollbar-thumb);
}

.binance-account-scroll.history::-webkit-scrollbar-thumb:hover,
.binance-account-scroll.history::-webkit-scrollbar-thumb:active {
  background-color: var(--binance-history-scrollbar-thumb-hover);
}

.binance-account-content {
  display: grid;
  width: min(100%, 1120px);
  margin: 0 auto;
  gap: 18px;
  padding: 4px clamp(20px, 3vw, 42px) 40px;
  outline: 0;
}

.binance-account-content.profit-calendar { width: min(80%, 896px); }

.binance-account-summary-card {
  border: 1px solid var(--binance-border);
  border-radius: 16px;
  background: var(--binance-surface);
  color: var(--binance-text);
}

.binance-account-unbound-card {
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--binance-text);
}

.binance-account-summary-card { position: relative; border: 1px solid var(--card-border-subtle); padding: 23px 34px 26px; }
