.binance-account-dialog header p { margin: 4px 0 0; color: var(--binance-text-muted); font-size: calc(11px + var(--app-font-size-offset)); line-height: 18px; }
.binance-account-dialog-close { display: grid; width: 34px; height: 34px; flex: 0 0 34px; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--binance-text-muted); font-size: calc(25px + var(--app-font-size-offset)); line-height: 1; cursor: pointer; }
.binance-account-dialog-close:hover:not(:disabled) { background: var(--binance-surface-hover); color: var(--binance-text); }
.binance-account-dialog-close:active:not(:disabled) { background: var(--binance-surface-active); }
.binance-account-dialog form { display: grid; gap: 17px; padding: 22px 26px 26px; }
.binance-account-dialog label { display: grid; gap: 7px; color: var(--binance-label-text); font-size: calc(12px + var(--app-font-size-offset)); }
.binance-account-dialog input { width: 100%; height: 46px; border: 1px solid var(--binance-border-strong); border-radius: 9px; outline: 0; background: var(--binance-surface); padding: 0 13px; color: var(--binance-text); font: inherit; font-size: calc(13px + var(--app-font-size-offset)); caret-color: var(--binance-text); }
.binance-account-dialog input::placeholder { color: var(--text-placeholder); }
.binance-account-dialog input:hover:not(:disabled) { border-color: color-mix(in srgb, var(--binance-text) 42%, var(--binance-border)); }
.binance-account-dialog input:focus { border-color: var(--binance-border-strong); box-shadow: none; }
.binance-account-dialog input:disabled { border-color: var(--binance-border); background: var(--binance-surface-disabled); color: var(--binance-text-muted); cursor: not-allowed; opacity: .72; }
.binance-account-secret-field,
.binance-account-otp-field { position: relative; display: flex; align-items: center; }
.binance-account-secret-field > input { padding-right: 48px; }
.binance-account-secret-field > button { position: absolute; right: 6px; display: grid; width: 34px; height: 34px; place-items: center; border: 0; border-radius: 7px; background: transparent; color: var(--binance-text-muted); cursor: pointer; }
.binance-account-secret-field > button:hover:not(:disabled) { background: var(--binance-surface-hover); color: var(--binance-text); }
.binance-account-secret-field svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.6; }
