.binance-account-otp-field > button { position: absolute; right: 6px; min-width: 104px; height: 34px; border: 0; border-radius: 7px; background: var(--binance-surface-hover); padding: 0 9px; color: var(--binance-text-secondary); font: inherit; font-size: calc(11px + var(--app-font-size-offset)); cursor: pointer; }
.binance-account-otp-field > button:hover:not(:disabled) { background: var(--binance-surface-active); color: var(--binance-text); }
.binance-account-otp-copy { border-radius: 9px; background: var(--binance-surface-hover); padding: 11px 13px; color: var(--binance-text-secondary); font-size: calc(12px + var(--app-font-size-offset)); line-height: 1.55; }
.binance-account-otp-copy strong { color: var(--binance-text); }
.binance-account-security-note { margin: -2px 0 0; color: var(--binance-text-muted); font-size: calc(11px + var(--app-font-size-offset)); line-height: 1.6; }
.binance-account-dialog-error { margin: -4px 0 0; border-radius: 8px; background: var(--binance-danger-bg); padding: 9px 11px; color: var(--binance-negative); font-size: calc(12px + var(--app-font-size-offset)); line-height: 1.5; }
.binance-account-dialog footer { padding-top: 2px; }
.binance-account-submit { width: 100%; min-height: 46px; border-color: var(--binance-action); background: var(--binance-action); color: var(--binance-action-text); font-size: calc(14px + var(--app-font-size-offset)); }
