.binance-account-submit.danger:active:not(:disabled) { border-color: var(--binance-danger-action-active); background: var(--binance-danger-action-active); transform: translateY(1px); }

.binance-account-page button:focus-visible,
.binance-account-dialog button:focus-visible { outline: 2px solid var(--binance-focus); outline-offset: 2px; }
