/* Avatar-free parallel task cards: compact hierarchy for narrow conversation panels. */
.subagent-cluster-row {
  display: block;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  border-radius: 13px;
  padding: 13px 14px 12px;
}

.subagent-cluster-row-main {
  width: 100%;
}

.subagent-cluster-identity {
  justify-content: space-between;
  gap: 10px;
}

.subagent-cluster-name {
  min-width: 0;
  overflow: hidden;
  font-size: calc(12px + var(--app-font-size-offset));
  font-weight: 650;
  line-height: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.subagent-cluster-profession {
  font-size: calc(10.5px + var(--app-font-size-offset));
  font-weight: 400;
}

.subagent-cluster-stage {
  min-height: 22px;
  flex: 0 0 auto;
  margin-left: auto;
  border-radius: 999px;
  padding: 2px 8px 2px 6px;
  line-height: 16px;
  white-space: nowrap;
}

.subagent-cluster-task {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  margin-top: 9px;
  border-top: 1px solid var(--line);
  padding-top: 9px;
  line-height: 18px;
}

.subagent-cluster-task > i {
  width: 5px;
  height: 5px;
  margin-top: 6px;
  border: 0;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.48;
}

.subagent-cluster-progress {
  width: 100%;
  grid-template-columns: auto minmax(0, 1fr);
  justify-content: stretch;
  gap: 10px;
  margin-top: 10px;
}

.subagent-cluster-progress-track {
  width: 100%;
}

html:not([data-theme="dark"]) .subagent-cluster-row {
  border-color: #e1e7ee;
  background: #fff;
  box-shadow: 0 5px 16px rgba(38, 63, 92, 0.055);
}

html:not([data-theme="dark"]) .subagent-cluster-row.starting,
html:not([data-theme="dark"]) .subagent-cluster-row.working {
  border-color: #cfe0f2;
  background: #f8fbff;
}

html:not([data-theme="dark"]) .subagent-cluster-row.completed {
  border-color: #d4e7de;
  background: #f8fcfa;
}

html:not([data-theme="dark"]) .subagent-cluster-row.failed {
  border-color: #efd6d6;
  background: #fffafa;
}

