  border-color: #eadfc9;
  background: #fffcf6;
}

html:not([data-theme="dark"]) .subagent-cluster-row:hover {
  border-color: #b8d2ec;
  background: #f7fbff;
  box-shadow: 0 8px 20px rgba(38, 76, 116, 0.085);
  transform: translateY(-1px);
}

