  transform: translateY(0);
}

html:not([data-theme="dark"]) .subagent-cluster-row:focus-visible {
  outline: 2px solid rgba(50, 133, 214, 0.5);
  outline-offset: 2px;
}

html[data-theme="dark"] .subagent-cluster-row {
  border-color: #30343a;
  background: #191b1f;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
}

html[data-theme="dark"] .subagent-cluster-row.starting,
html[data-theme="dark"] .subagent-cluster-row.working {
  border-color: #324b64;
  background: #18212a;
}

html[data-theme="dark"] .subagent-cluster-row.completed {
  border-color: #304a40;
  background: #19221f;
}

html[data-theme="dark"] .subagent-cluster-row.failed {
  border-color: #533537;
  background: #241a1c;
}

html[data-theme="dark"] .subagent-cluster-row.interrupted {
