  box-shadow: 0 9px 24px rgba(0, 0, 0, 0.26);
  transform: translateY(-1px);
}

html[data-theme="dark"] .subagent-cluster-row:active {
  background: #1a222a;
  box-shadow: 0 4px 13px rgba(0, 0, 0, 0.22);
  transform: translateY(0);
}

html[data-theme="dark"] .subagent-cluster-row:focus-visible {
  outline: 2px solid rgba(105, 176, 244, 0.62);
  outline-offset: 2px;
