@media (max-width: 520px) {
  .subagent-cluster-row {
    padding: 12px;
  }

  .subagent-cluster-name {
    font-size: calc(11.5px + var(--app-font-size-offset));
  }

  .subagent-cluster-progress {
    gap: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .subagent-cluster-row {
    transition: none;
  }
}
/* Personal strategy creation, simulation and feedback flow. Keep light and
   dark surfaces in sync so the minimal interaction remains legible in every
   state. */
.personal-strategy-backdrop {
  background: rgba(15, 23, 42, 0.32);
  backdrop-filter: blur(8px);
  z-index: 80;
}
.personal-strategy-dialog {
  position: fixed;
  inset: 50% auto auto 50%;
  transform: translate(-50%, -50%);
  width: min(680px, calc(100vw - 32px));
  max-height: min(760px, calc(100vh - 44px));
  margin: 0;
  border: 1px solid rgba(15, 23, 42, 0.12);
  border-radius: 22px;
  padding: 0;
  overflow: auto;
  color: #172033;
  background: #ffffff;
  box-shadow: 0 28px 90px rgba(15, 23, 42, 0.24);
  z-index: 81;
}
.personal-strategy-dialog::backdrop { background: transparent; }
.personal-strategy-dialog-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  padding: 24px 26px 18px;
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
}
.personal-strategy-dialog-header h2 { margin: 3px 0 5px; font-size: calc(21px + var(--app-font-size-offset)); }
.personal-strategy-dialog-header p { margin: 0; color: #667085; font-size: calc(13px + var(--app-font-size-offset)); }
.personal-strategy-kicker { color: #3a67d8; font-size: calc(10px + var(--app-font-size-offset)); font-weight: 700; letter-spacing: .14em; }
.personal-strategy-close {
  width: 30px; height: 30px; border: 0; border-radius: 9px; background: transparent;
  color: #667085; font-size: calc(23px + var(--app-font-size-offset)); line-height: 1; cursor: pointer;
}
.personal-strategy-close:hover, .personal-strategy-close:focus-visible { color: #172033; background: #eef2f8; outline: none; }
.personal-strategy-close:active { transform: translateY(1px); }
.personal-strategy-dialog-body { display: grid; gap: 15px; padding: 20px 26px 26px; }
.personal-strategy-field { display: grid; gap: 7px; color: #475467; font-size: calc(12px + var(--app-font-size-offset)); font-weight: 600; }
.personal-strategy-field input, .personal-strategy-field textarea {
  width: 100%; box-sizing: border-box; border: 1px solid #d8dee9; border-radius: 12px; padding: 11px 12px;
  color: #172033; background: #f8fafc; font: inherit; font-weight: 400; resize: vertical; transition: border-color .15s, box-shadow .15s, background .15s;
}
.personal-strategy-field input:hover, .personal-strategy-field textarea:hover { border-color: #b5c0d1; }
.personal-strategy-field input:focus, .personal-strategy-field textarea:focus { border-color: #4f72da; background: #fff; box-shadow: 0 0 0 3px rgba(79,114,218,.16); outline: none; }
.personal-strategy-preview, .personal-strategy-simulation, .personal-strategy-feedback { border: 1px solid #e1e7f0; border-radius: 15px; padding: 14px 15px; background: #fbfcfe; }
.personal-strategy-preview p, .personal-strategy-simulation p { margin: 10px 0 0; white-space: pre-wrap; color: #475467; font-size: calc(13px + var(--app-font-size-offset)); line-height: 1.58; }
.personal-strategy-preview-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.personal-strategy-preview-title span { color: #7a8699; font-size: calc(11px + var(--app-font-size-offset)); }
.personal-strategy-chip-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.personal-strategy-chip-row span { border-radius: 99px; padding: 4px 8px; color: #3156bd; background: #e9efff; font-size: calc(11px + var(--app-font-size-offset)); }
.personal-strategy-warning, .personal-strategy-note { margin-top: 12px; border-radius: 10px; padding: 10px 11px; font-size: calc(12px + var(--app-font-size-offset)); }
.personal-strategy-warning { color: #8a4b00; background: #fff6df; }
.personal-strategy-note { color: #526173; background: #f1f4f8; }
.personal-strategy-warning p, .personal-strategy-note p { margin: 4px 0 0; color: inherit; font-size: calc(12px + var(--app-font-size-offset)); }
.personal-strategy-simulation small { display: block; margin-top: 8px; color: #7a8699; }
.personal-strategy-feedback { display: grid; gap: 10px; }
.personal-strategy-feedback-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }
.personal-strategy-feedback-actions .ghost-button { min-height: 36px; border: 1px solid #d8dee9; border-radius: 10px; padding: 0 12px; color: #526173; background: transparent; font: inherit; font-size: calc(12px + var(--app-font-size-offset)); cursor: pointer; }
.personal-strategy-feedback-actions .ghost-button:hover, .personal-strategy-feedback-actions .ghost-button:focus-visible { color: #294a9e; border-color: #9ab0ef; background: #f1f4ff; outline: none; }
.personal-strategy-dialog-actions { display: flex; justify-content: flex-end; gap: 9px; }
.personal-strategy-dialog-actions button, .personal-strategy-feedback button { min-height: 36px; border-radius: 10px; padding: 0 14px; border: 1px solid transparent; font: inherit; font-size: calc(12px + var(--app-font-size-offset)); font-weight: 650; cursor: pointer; transition: transform .12s, filter .12s, background .12s; }
.personal-strategy-dialog-actions button:hover:not(:disabled), .personal-strategy-feedback button:hover:not(:disabled) { filter: brightness(.98); }
.personal-strategy-dialog-actions button:active:not(:disabled), .personal-strategy-feedback button:active:not(:disabled) { transform: translateY(1px); }
.personal-strategy-dialog-actions button:focus-visible, .personal-strategy-feedback button:focus-visible { outline: 3px solid rgba(79,114,218,.24); outline-offset: 2px; }
.personal-strategy-dialog-actions button:disabled, .personal-strategy-feedback button:disabled { cursor: not-allowed; opacity: .52; }
.personal-strategy-dialog-actions .primary-button { color: #fff; background: #3f63ca; }
.personal-strategy-dialog-actions .secondary-button, .personal-strategy-feedback .secondary-button { color: #294a9e; background: #edf2ff; border-color: #d7e1ff; }
.personal-strategy-error { margin: 0; border-radius: 10px; padding: 9px 11px; color: #b42318; background: #fff0ef; font-size: calc(12px + var(--app-font-size-offset)); }

