html[data-theme="dark"] .personal-strategy-dialog-actions .primary-button { color: #fff; background: #5474dc; }
html[data-theme="dark"] .personal-strategy-dialog-actions .secondary-button, html[data-theme="dark"] .personal-strategy-feedback .secondary-button { color: #d4ddff; background: #263861; border-color: #3a4d80; }
html[data-theme="dark"] .personal-strategy-feedback-actions .ghost-button { color: #b8c3d5; border-color: #43516b; background: transparent; }
html[data-theme="dark"] .personal-strategy-feedback-actions .ghost-button:hover, html[data-theme="dark"] .personal-strategy-feedback-actions .ghost-button:focus-visible { color: #e0e7ff; border-color: #7188d9; background: #263861; }
html[data-theme="dark"] .personal-strategy-error { color: #ffb5b0; background: #4b2528; }

html[data-theme="dark"] .settings-referral-entry { border-color: #343942; color: #f0f2f5; background: linear-gradient(135deg, #25282e, #202329); }
html[data-theme="dark"] .settings-referral-entry:hover { border-color: #555c66; background: #2b2f35; box-shadow: 0 8px 20px rgba(0, 0, 0, .24); }
html[data-theme="dark"] .settings-referral-entry:active { border-color: #656c76; background: #31353c; box-shadow: none; }
html[data-theme="dark"] .settings-referral-entry:focus-visible { outline-color: #9ca3ad; }
html[data-theme="dark"] .settings-referral-entry-icon { border: 1px solid rgba(255, 255, 255, .14); background: #08090b; box-shadow: 0 6px 14px rgba(0, 0, 0, .34); }
html[data-theme="dark"] .settings-referral-entry > span small { color: #9ca3ad; }
